head.script:
{
  "@context": "https://schema.org",
  "@graph": [
    {
      "@type": "WebSite",
      "@id": "https://updates.indigenworld.com/#website",
      "url": "https://updates.indigenworld.com/",
      "name": "Indigen World Updates",
      "description": "Release notes, feature updates and notes from the field across the Indigen World ecosystem.",
      "inLanguage": "en",
      "publisher": { "@id": "https://indigenworld.com/#organization" },
      "potentialAction": {
        "@type": "SearchAction",
        "target": { "@type": "EntryPoint", "urlTemplate": "https://updates.indigenworld.com/search?q={search_term_string}" },
        "query-input": "required name=search_term_string"
      }
    },
    {
      "@type": "Organization",
      "@id": "https://indigenworld.com/#organization",
      "name": "Indigen World",
      "url": "https://indigenworld.com/",
      "logo": "https://indigenworld.com/og-image-updates.png"
    }
  ]
}

head.b:skin:
/*
<Variable name="keycolor" description="Main colour" type="color" default="#19327f" value="#19327f"/>

<Group description="Brand palette" selector="body">
  <Variable name="brand.indigo" description="Royal blue" type="color" default="#19327f" value="#19327f"/>
  <Variable name="brand.indigoDeep" description="Deep navy" type="color" default="#0f1830" value="#0f1830"/>
  <Variable name="brand.gold" description="Cyan accent" type="color" default="#22d3ee" value="#22d3ee"/>
  <Variable name="brand.goldSoft" description="Soft blue" type="color" default="#cfe0ff" value="#cfe0ff"/>
  <Variable name="brand.terracotta" description="Electric blue" type="color" default="#2f6bff" value="#2f6bff"/>
  <Variable name="brand.green" description="Green" type="color" default="#168466" value="#168466"/>
  <Variable name="brand.cream" description="Page ground" type="color" default="#f6f7fb" value="#f6f7fb"/>
  <Variable name="brand.sand" description="Blue mist" type="color" default="#eaf0ff" value="#eaf0ff"/>
</Group>

<Group description="Typography" selector="body">
  <Variable name="type.ui" description="Interface font" type="font" default="normal normal 16px 'Noto Sans', system-ui, sans-serif" value="normal normal 16px 'Noto Sans', system-ui, sans-serif"/>
  <Variable name="type.body" description="Article body font" type="font" default="normal normal 17px 'Noto Serif', Georgia, serif" value="normal normal 17px 'Noto Serif', Georgia, serif"/>
  <Variable name="type.display" description="Headline font" type="font" default="normal normal 40px 'Noto Serif Display', 'Noto Serif', Georgia, serif" value="normal normal 40px 'Noto Serif Display', 'Noto Serif', Georgia, serif"/>
</Group>

<Group description="Layout" selector="body">
  <Variable name="layout.width" description="Page width" type="length" default="1200px" min="960px" max="1440px" value="1200px"/>
  <Variable name="layout.article" description="Article column width" type="length" default="760px" min="600px" max="900px" value="760px"/>
  <Variable name="layout.radius" description="Corner radius" type="length" default="18px" min="0px" max="28px" value="18px"/>
</Group>
*/

/* ==========================================================================
   1. Tokens
   --------------------------------------------------------------------------
   The palette is the public website's theme, apps/website/src/styles/
   comitia-theme.css: deep navy, royal and electric blue, a cyan accent and a
   blue-white ground. Like the website, the token names keep their original
   roles (--gold is the accent, --terracotta the action blue) so every rule
   below reads the same as before. The validator checks these defaults against
   that file, so change the website first.
   ========================================================================== */

:root{
  color-scheme:light;

  --indigo:$(brand.indigo);
  --indigo-deep:$(brand.indigoDeep);
  --gold:$(brand.gold);
  --gold-soft:$(brand.goldSoft);
  --terracotta:$(brand.terracotta);
  --green:$(brand.green);
  --cream:$(brand.cream);
  --sand:$(brand.sand);
  --blue-line:#8eb4ff;
  --blue-pale:#bcd2ff;

  --bg:var(--cream);
  --bg-alt:var(--sand);
  --surface:#ffffff;
  --surface-2:#f2f6ff;
  --ink:#0f1830;
  --ink-soft:#4a5878;
  --ink-mute:#5d667b;
  --line:rgba(15,24,48,.11);
  --line-2:rgba(15,24,48,.22);
  --accent-ink:#1f50d6;
  --link:#1f50d6;
  --link-hover:var(--indigo);
  --code-ink:#1a3ea8;
  --info-ink:#1f50d6;
  --success-ink:#0f7a5a;
  --warn-ink:#8a5a04;
  --topic-release:#168466;
  --topic-feature:#12b5cf;
  --topic-engineering:#2f6bff;
  --topic-community:#d99a1e;
  --topic-language:#5b45c4;
  --focus:#2f6bff;
  --control-border:#7a84a0;
  --action-bg:#2c66f5;
  --action-hover:var(--indigo);
  --action-ink:#fff;
  --success-bg:#0f7a5a;
  --callout-bg:var(--surface);
  --on-dark:#f5f8ff;
  --on-dark-soft:rgba(255,255,255,.62);
  --select-bg:var(--gold-soft);
  --select-fg:var(--indigo-deep);
  --code-bg:#0f1830;
  --code-fg:#e3eaf8;

  --shadow-1:0 1px 2px rgba(15,24,48,.05),0 10px 30px rgba(15,24,48,.055);
  --shadow-2:0 2px 8px rgba(15,24,48,.06),0 18px 44px rgba(15,24,48,.11);
  --hero-bg:
    radial-gradient(circle at 78% 20%,rgba(34,211,238,.23),transparent 30%),
    radial-gradient(circle at 10% 100%,rgba(47,107,255,.22),transparent 34%),
    linear-gradient(145deg,#0b1225,#19327f 62%,#2457d6);
  --dots:radial-gradient(rgba(255,255,255,.28) 1px,transparent 1px);

  --shell:$(layout.width);
  --article-w:$(layout.article);
  --radius:$(layout.radius);
  --radius-sm:10px;
  --pill:999px;

  --font-ui:$(type.ui.family);
  --font-body:$(type.body.family);
  --font-display:$(type.display.family);
  --font-mono:ui-monospace,SFMono-Regular,Menlo,Consolas,monospace;
  --fs-ui:$(type.ui.size);
  --fs-body:$(type.body.size);

  --ease:cubic-bezier(.2,.7,.2,1);
  --dur:220ms;
  --head-h:76px;
}

/* Dark palette. The website has no dark mode, so this is the navy of its hero
   and footer, with the blues lifted so links and accents keep their contrast on
   a dark ground. */
:root[data-theme="dark"]{
  color-scheme:dark;
  --bg:#0b1225;
  --bg-alt:#080e1d;
  --surface:#111c36;
  --surface-2:#17264a;
  --ink:#f5f7fb;
  --ink-soft:#bcc7dd;
  --ink-mute:#9aa8c2;
  --line:rgba(255,255,255,.11);
  --line-2:rgba(255,255,255,.22);
  --terracotta:#6d99ff;
  --green:#34c28f;
  --accent-ink:#8eb4ff;
  --link:#8eb4ff;
  --link-hover:#cfe0ff;
  --code-ink:#bcd2ff;
  --info-ink:#8eb4ff;
  --success-ink:#5fd3a4;
  --warn-ink:#f2bf6b;
  --topic-release:#34c28f;
  --topic-feature:#22d3ee;
  --topic-engineering:#6d99ff;
  --topic-community:#f2bf6b;
  --topic-language:#b3a4f5;
  --focus:#8eb4ff;
  --control-border:#8a94ad;
  --action-hover:#1f50d6;
  --callout-bg:var(--surface-2);
  --select-bg:rgba(47,107,255,.42);
  --select-fg:#fff;
  --code-bg:#060b18;
  --code-fg:#e3eaf8;
  --shadow-1:0 1px 2px rgba(0,0,0,.4),0 6px 18px rgba(0,0,0,.28);
  --shadow-2:0 2px 8px rgba(0,0,0,.45),0 24px 56px rgba(0,0,0,.45);
}

@media (prefers-color-scheme:dark){
  :root:not([data-theme="light"]){
    color-scheme:dark;
    --bg:#0b1225;
    --bg-alt:#080e1d;
    --surface:#111c36;
    --surface-2:#17264a;
    --ink:#f5f7fb;
    --ink-soft:#bcc7dd;
    --ink-mute:#9aa8c2;
    --line:rgba(255,255,255,.11);
    --line-2:rgba(255,255,255,.22);
    --terracotta:#6d99ff;
    --green:#34c28f;
    --accent-ink:#8eb4ff;
    --link:#8eb4ff;
    --link-hover:#cfe0ff;
    --code-ink:#bcd2ff;
    --info-ink:#8eb4ff;
    --success-ink:#5fd3a4;
    --warn-ink:#f2bf6b;
    --topic-release:#34c28f;
    --topic-feature:#22d3ee;
    --topic-engineering:#6d99ff;
    --topic-community:#f2bf6b;
    --topic-language:#b3a4f5;
    --focus:#8eb4ff;
    --control-border:#8a94ad;
    --action-hover:#1f50d6;
    --callout-bg:var(--surface-2);
    --select-bg:rgba(47,107,255,.42);
    --select-fg:#fff;
    --code-bg:#060b18;
    --code-fg:#e3eaf8;
    --shadow-1:0 1px 2px rgba(0,0,0,.4),0 6px 18px rgba(0,0,0,.28);
    --shadow-2:0 2px 8px rgba(0,0,0,.45),0 24px 56px rgba(0,0,0,.45);
  }
}

/* ==========================================================================
   2. Reset and base
   ========================================================================== */

*,*::before,*::after{box-sizing:border-box}
html{-webkit-text-size-adjust:100%;font-size:var(--fs-ui);scroll-behavior:smooth;scroll-padding-top:96px}
body{
  margin:0;min-width:320px;
  background:var(--bg);color:var(--ink);
  font-family:var(--font-ui);font-size:1rem;line-height:1.6;
  -webkit-font-smoothing:antialiased;text-rendering:optimizeLegibility;
  overflow-wrap:break-word;
}
img,svg,video,iframe,canvas{display:block;max-width:100%}
img{height:auto}
a{color:inherit;text-decoration:none}
button,input,select,textarea{font:inherit;color:inherit}
button{cursor:pointer;background:none;border:0;padding:0;color:inherit}
ul,ol{margin:0;padding:0}
li{list-style:none}
h1,h2,h3,h4,h5,h6,p,figure,blockquote,dl,dd{margin:0}
table{border-collapse:collapse}
::selection{background:var(--select-bg);color:var(--select-fg)}
:focus-visible{outline:2px solid var(--focus);outline-offset:3px;border-radius:4px}
[hidden]{display:none!important}

.iw-shell{width:min(var(--shell),calc(100% - 32px));margin-inline:auto}
@media (min-width:700px){.iw-shell{width:min(var(--shell),calc(100% - 56px))}}

.iw-skip{
  position:fixed;z-index:400;top:10px;left:10px;transform:translateY(-160%);
  padding:11px 18px;border-radius:var(--radius-sm);
  background:var(--action-bg);color:var(--action-ink);font-weight:700;font-size:.88rem;
  transition:transform var(--dur) var(--ease);
}
.iw-skip:focus{transform:none}

.iw-sr{
  position:absolute!important;width:1px;height:1px;padding:0;margin:-1px;
  overflow:hidden;clip:rect(0 0 0 0);white-space:nowrap;border:0
}

/* Brand mark, coloured the way the website's header draws it. */
.iw-mark{width:34px;height:34px;flex:0 0 auto}
.iw-mark__frame{fill:none;stroke:var(--blue-line);stroke-width:2.4;stroke-linecap:round;stroke-linejoin:round}
.iw-mark__line{fill:none;stroke:#fff;stroke-width:2.2;stroke-linecap:round}
.iw-mark__sun{fill:var(--gold)}

/* Woven motif, kept from the original theme and recoloured to the website's
   blues. The website's own footer still carries the same weave. */
.iw-kente{
  background-image:
    repeating-linear-gradient(45deg,transparent 0 15px,rgba(207,224,255,.11) 15px 17px,transparent 17px 32px),
    repeating-linear-gradient(-45deg,transparent 0 15px,rgba(47,107,255,.12) 15px 17px,transparent 17px 32px);
}

/* ==========================================================================
   3. Reading progress
   ========================================================================== */

.iw-progress{position:fixed;z-index:120;inset:0 0 auto;height:3px;pointer-events:none}
.iw-progress i{
  display:block;height:100%;width:0;
  background:linear-gradient(90deg,var(--gold),var(--terracotta));
  transition:width 90ms linear;
}

/* ==========================================================================
   4. Header, navigation, search
   ========================================================================== */

/* The website's header: a glass bar floating 10px below the top of the
   viewport. The strip around it is transparent and lets clicks through, and
   the homepage hero slides up underneath it, as the website's hero does. */
.iw-head{
  --focus:var(--gold-soft);
  position:sticky;z-index:90;top:0;color:var(--on-dark);
  padding-top:10px;pointer-events:none;
}
.iw-head__in{
  position:relative;isolation:isolate;
  display:flex;flex-wrap:wrap;align-items:center;gap:12px;
  min-height:64px;padding:9px 12px 9px 16px;
  border:1px solid rgba(255,255,255,.15);border-radius:20px;
  background:linear-gradient(115deg,rgba(255,255,255,.1),transparent 48%),rgba(15,24,48,.88);
  box-shadow:0 16px 42px rgba(15,24,48,.2),inset 0 1px 0 rgba(255,255,255,.1);
  -webkit-backdrop-filter:blur(22px) saturate(150%);
  backdrop-filter:blur(22px) saturate(150%);
  pointer-events:auto;
}
.iw-head__in::after{
  content:"";position:absolute;z-index:-1;inset:0 auto auto 8%;width:44%;height:1px;
  background:linear-gradient(90deg,transparent,rgba(142,180,255,.78),transparent);
}
@supports not ((-webkit-backdrop-filter:blur(1px)) or (backdrop-filter:blur(1px))){
  .iw-head__in,.iw-searchpane > .iw-shell{background:rgba(15,24,48,.96)}
}

.iw-masthead{flex:1 1 220px;min-width:0}
.iw-masthead .widget{min-width:0}
.iw-masthead .iw-brand__text strong{overflow-wrap:anywhere}
@media (max-width:479px){
  .iw-head__in{gap:8px;padding-inline:10px 8px}
  .iw-masthead{flex:1 1 0}
  .iw-masthead .iw-brand{gap:6px}
  .iw-masthead .iw-brand__text strong{font-size:.82rem}
  .iw-masthead .iw-brand__text small{display:none}
}
.iw-brand{display:flex;align-items:center;gap:11px;min-width:0;margin-right:auto}
.iw-brand__text{display:flex;flex-direction:column;line-height:1.2;min-width:0}
.iw-brand__text strong{font-size:.98rem;font-weight:800;letter-spacing:-.005em;color:#fff}
.iw-brand__text small{
  font-size:.7rem;color:var(--on-dark-soft);
  letter-spacing:.05em;text-transform:uppercase;
  overflow:hidden;text-overflow:ellipsis;white-space:nowrap;
}
.iw-brand__img{max-height:38px;width:auto}

/* Mobile: the nav is a collapsible second row. It becomes an inline
   row at the desktop breakpoint. Using a grid-rows collapse rather than
   a fixed overlay avoids the backdrop-filter containing-block trap. */
.iw-nav{order:3;flex:1 0 100%;display:grid;grid-template-rows:0fr;transition:grid-template-rows var(--dur) var(--ease)}
.iw-nav__in{min-height:0;overflow:hidden}
.iw-nav.is-open{grid-template-rows:1fr}
.iw-nav .section{display:contents}
.iw-nav .widget{display:block}
.iw-navlist{display:flex;flex-direction:column;padding-bottom:12px}
.iw-navlist a{
  display:block;padding:13px 2px;font-size:.92rem;font-weight:700;
  color:rgba(255,255,255,.78);border-bottom:1px solid rgba(255,255,255,.08);
  transition:color var(--dur) var(--ease),padding-inline var(--dur) var(--ease),background var(--dur) var(--ease);
}
.iw-navlist a:hover,.iw-navlist a:focus-visible,.iw-navlist li.is-current a{
  color:#fff;padding-inline:10px;
  background:linear-gradient(90deg,rgba(47,107,255,.2),transparent);
}

/* Blogger labels become a real update filter in the header. The native
   details element keeps the control usable before JavaScript loads. */
.iw-filter{position:relative;margin-top:8px;color:#fff}
.iw-filter summary{
  display:flex;align-items:center;gap:8px;min-height:44px;padding:10px 12px;
  border:1px solid rgba(255,255,255,.14);border-radius:12px;
  background:rgba(255,255,255,.07);color:#fff;font-size:.86rem;font-weight:700;
  cursor:pointer;list-style:none;
}
.iw-filter summary::-webkit-details-marker{display:none}
.iw-filter summary::after{content:"\2304";margin-left:auto;font-size:.82rem;transition:transform var(--dur) var(--ease)}
.iw-filter[open] summary::after{transform:rotate(180deg)}
.iw-filter summary svg{width:17px;height:17px;fill:none;stroke:currentColor;stroke-width:1.9;stroke-linecap:round;stroke-linejoin:round}
.iw-filter__menu{
  display:grid;gap:4px;margin-top:7px;padding:7px;border:1px solid rgba(255,255,255,.14);
  border-radius:14px;background:rgba(4,10,25,.5)
}
.iw-filter__option{
  display:flex;align-items:center;gap:9px;min-height:42px;padding:8px 10px;border-radius:9px;
  color:rgba(255,255,255,.78);font-size:.84rem;font-weight:650;
}
.iw-filter__option::before{content:"";width:7px;height:7px;border-radius:2px;background:var(--topic-feature);flex:0 0 auto}
.iw-filter__option:hover,.iw-filter__option:focus-visible,.iw-filter__option.is-current{color:#fff;background:rgba(47,107,255,.2)}
.iw-filter__count{margin-left:auto;color:var(--on-dark-soft);font-size:.7rem;font-variant-numeric:tabular-nums}

.iw-head__act{display:flex;align-items:center;gap:7px;order:2;flex:0 0 auto}
.iw-ibtn{
  display:grid;place-items:center;width:40px;height:40px;border-radius:12px;
  border:1px solid rgba(255,255,255,.18);background:rgba(255,255,255,.07);color:#fff;
  transition:background var(--dur) var(--ease),border-color var(--dur) var(--ease),transform var(--dur) var(--ease);
}
.iw-ibtn:hover,.iw-ibtn:focus-visible{
  background:rgba(255,255,255,.16);border-color:rgba(142,180,255,.48);transform:translateY(-1px);
}
.iw-ibtn svg{width:19px;height:19px;fill:none;stroke:currentColor;stroke-width:1.9;stroke-linecap:round;stroke-linejoin:round}
.iw-ibtn .iw-i-moon{display:none}
:root[data-theme="dark"] .iw-ibtn .iw-i-moon{display:block}
:root[data-theme="dark"] .iw-ibtn .iw-i-sun{display:none}
@media (prefers-color-scheme:dark){
  :root:not([data-theme="light"]) .iw-ibtn .iw-i-moon{display:block}
  :root:not([data-theme="light"]) .iw-ibtn .iw-i-sun{display:none}
}

@media (min-width:980px){
  /* display:contents collapses the section and widget wrappers so the pill
     itself becomes the flex item and shrinks to its own content. */
  .iw-nav{order:2;flex:0 1 auto;display:flex;justify-content:center;margin-inline:auto}
  .iw-nav__in{display:contents;overflow:visible}
  .iw-nav .widget{display:contents}
  .iw-navlist{
    flex-direction:row;align-items:center;gap:2px;padding:4px;
    border:1px solid rgba(255,255,255,.09);border-radius:var(--pill);
    background:rgba(4,10,25,.22);
  }
  .iw-navlist a{
    padding:8px 13px;border:1px solid transparent;border-radius:var(--pill);
    font-size:.85rem;font-weight:600;white-space:nowrap;
  }
  .iw-navlist a:hover,.iw-navlist a:focus-visible,.iw-navlist li.is-current a{
    background:rgba(47,107,255,.15);border-color:rgba(142,180,255,.24);padding-inline:13px;
  }
  .iw-navlist li.is-current a{box-shadow:inset 0 -1px 0 rgba(142,180,255,.58)}
  .iw-filter{margin-top:0;flex:0 0 auto}
  .iw-filter summary{min-height:38px;padding:8px 12px;border-radius:var(--pill);background:rgba(4,10,25,.22)}
  .iw-filter summary::after{margin-left:2px}
  .iw-filter__menu{
    position:absolute;top:calc(100% + 8px);right:0;width:250px;max-height:min(420px,calc(100vh - var(--head-h) - 32px));
    overflow-y:auto;margin-top:0;padding:8px;border-color:var(--line-2);background:var(--surface);box-shadow:var(--shadow-2)
  }
  .iw-filter__option{color:var(--ink-soft)}
  .iw-filter__option:hover,.iw-filter__option:focus-visible,.iw-filter__option.is-current{color:var(--ink);background:var(--surface-2)}
  .iw-filter__count{color:var(--ink-mute)}
  .iw-menubtn{display:none}
}

/* Search panel. Sticky under the measured header, but zero-height, so the
   glass panel hangs below it without pushing the hero down from under the
   header. The shell is offset with top rather than margin, which would
   collapse through the empty parent and move it after all. */
.iw-searchpane{
  --focus:var(--gold-soft);color-scheme:dark;
  position:sticky;top:var(--head-h);z-index:80;
  height:0;overflow:visible;pointer-events:none;
}
.iw-searchpane > .iw-shell{
  position:relative;top:8px;
  padding:12px;border:1px solid rgba(255,255,255,.15);border-radius:18px;
  background:linear-gradient(115deg,rgba(255,255,255,.08),transparent 48%),rgba(15,24,48,.94);
  box-shadow:0 22px 50px rgba(10,22,43,.26);
  -webkit-backdrop-filter:blur(22px) saturate(150%);
  backdrop-filter:blur(22px) saturate(150%);
  pointer-events:auto;
}
.iw-searchpane[hidden]{display:none}
.iw-searchform{display:flex;gap:9px;align-items:center}
.iw-searchform input{
  flex:1 1 auto;min-width:0;padding:13px 16px;border-radius:var(--radius-sm);
  border:1px solid rgba(255,255,255,.5);background:rgba(255,255,255,.07);
  color:#fff;font-size:.95rem;
}
.iw-searchform input::placeholder{color:rgba(255,255,255,.72);opacity:1}
.iw-searchform input:focus{outline:none;border-color:var(--blue-line);background:rgba(255,255,255,.12)}
.iw-searchform button{
  padding:13px 20px;border-radius:var(--radius-sm);flex:0 0 auto;
  background:var(--action-bg);color:var(--action-ink);font-weight:700;font-size:.9rem;
}
.iw-searchform button:hover{background:var(--action-hover)}

/* ==========================================================================
   5. Homepage hero
   ========================================================================== */

/* The website's home hero: navy into electric blue with a cyan glow and a
   faint dot grid. It starts under the floating header. */
.iw-hero{
  --focus:var(--gold-soft);
  position:relative;isolation:isolate;overflow:hidden;
  margin-top:calc(-1 * var(--head-h));
  color:var(--on-dark);
  background:var(--hero-bg);
  border-bottom:1px solid rgba(142,180,255,.16);
}
.iw-hero::before,.iw-hero::after{content:"";position:absolute;z-index:-1;pointer-events:none}
.iw-hero::before{
  width:300px;aspect-ratio:1;top:-150px;right:-150px;
  border:1px solid rgba(142,180,255,.14);border-radius:50%;
  box-shadow:
    0 0 0 42px rgba(47,107,255,.035),
    0 0 0 84px rgba(34,211,238,.025),
    0 0 0 126px rgba(255,255,255,.02);
}
.iw-hero::after{
  inset:0;opacity:.12;
  background-image:
    var(--dots),
    linear-gradient(125deg,transparent 0 65%,rgba(142,180,255,.12) 65.2% 65.5%,transparent 65.7%);
  background-size:22px 22px,auto;
}
.iw-hero__in{position:relative;z-index:1;padding:calc(var(--head-h) + 64px) 0 72px}
.iw-hero__grid{display:grid;gap:36px;align-items:end}
@media (min-width:900px){.iw-hero__grid{grid-template-columns:minmax(0,1fr) minmax(220px,280px);gap:clamp(40px,6vw,88px)}}
.iw-hero__mark{display:block;width:64px;height:3px;margin:26px 0 22px;border-radius:2px;background:linear-gradient(90deg,var(--gold),var(--terracotta))}
.iw-hero__rail{display:flex;flex-direction:column;border-top:1px solid rgba(255,255,255,.16)}
.iw-hero__rail span{
  position:relative;padding:15px 0 15px 20px;border-bottom:1px solid rgba(255,255,255,.16);
  font-size:.84rem;font-weight:650;line-height:1.45;color:rgba(255,255,255,.8);
}
.iw-hero__rail span::before{
  content:"";position:absolute;left:0;top:21px;width:7px;height:7px;border-radius:50%;
  background:var(--gold);box-shadow:0 0 0 4px rgba(34,211,238,.14);
}
@keyframes iw-rise{from{opacity:0;transform:translateY(14px)}to{opacity:1;transform:none}}
.iw-hero .iw-eyebrow,.iw-hero__title,.iw-hero__mark,.iw-hero__lede,.iw-hero__actions,.iw-hero__rail span{
  animation:iw-rise .6s cubic-bezier(.22,.61,.36,1) both;
}
.iw-hero__title{animation-delay:.07s}
.iw-hero__mark{animation-delay:.14s}
.iw-hero__lede{animation-delay:.2s}
.iw-hero__actions{animation-delay:.26s}
.iw-hero__rail span:nth-child(1){animation-delay:.3s}
.iw-hero__rail span:nth-child(2){animation-delay:.37s}
.iw-hero__rail span:nth-child(3){animation-delay:.44s}
.iw-eyebrow{
  display:inline-flex;align-items:center;gap:9px;margin-bottom:16px;
  font-size:.73rem;font-weight:700;letter-spacing:.14em;text-transform:uppercase;
  color:var(--blue-pale);
}
.iw-eyebrow::before{
  content:"";width:7px;height:7px;border-radius:50%;flex:0 0 auto;
  background:var(--gold);box-shadow:0 0 0 4px rgba(34,211,238,.14);
}
.iw-hero__title{
  font-family:var(--font-display);font-size:clamp(2.5rem,7vw,5.2rem);line-height:.98;letter-spacing:-.025em;
  font-weight:600;color:#fff;text-wrap:balance;max-width:16ch;
}
.iw-hero__lede{
  margin-top:16px;max-width:56ch;font-size:clamp(1rem,2.1vw,1.13rem);
  line-height:1.65;color:rgba(255,255,255,.78);text-wrap:pretty;
}
.iw-hero__actions{display:flex;flex-wrap:wrap;gap:10px;margin-top:26px}
.iw-btn{
  display:inline-flex;align-items:center;gap:9px;padding:11px 22px;min-height:44px;
  border-radius:var(--pill);font-size:.9rem;font-weight:700;
  border:2px solid transparent;
  transition:background var(--dur) var(--ease),border-color var(--dur) var(--ease),transform var(--dur) var(--ease),box-shadow var(--dur) var(--ease);
}
.iw-btn--primary{background:var(--action-bg);color:var(--action-ink);box-shadow:0 9px 24px rgba(47,107,255,.22)}
.iw-btn--primary:hover{background:var(--action-hover);box-shadow:0 13px 30px rgba(47,107,255,.28);transform:translateY(-2px)}
.iw-btn--ghost{border-color:rgba(255,255,255,.5);color:#fff;background:transparent}
.iw-btn--ghost:hover{background:rgba(255,255,255,.12);transform:translateY(-2px)}
.iw-btn svg{width:16px;height:16px;fill:none;stroke:currentColor;stroke-width:2;stroke-linecap:round;stroke-linejoin:round}

/* ==========================================================================
   6. Page shell and layout
   ========================================================================== */

.iw-main{padding-block:44px 72px}
.iw-layout{display:grid;gap:40px;align-items:start}
.iw-layout > *,.iw-card__body,.iw-cols > *{min-width:0}
.iw-layout--index{grid-template-columns:minmax(0,1fr)}
@media (min-width:1040px){
  .iw-layout--index{grid-template-columns:minmax(0,1fr) 312px;gap:52px}
}
.iw-layout--article{grid-template-columns:minmax(0,1fr)}
.iw-layout--article > .iw-side{display:none}
.iw-layout--index > .iw-rail{display:none}
.iw-layout--index > .iw-share-rail{display:none}
.iw-layout--article #FeaturedPost1{display:none!important}
.iw-layout--article > #main{max-width:var(--article-w);margin-inline:auto;width:100%}
@media (min-width:1180px){
  /* Flexible gutters, so the article keeps its full measure and the table of
     contents takes whatever is left on the right. Fixed-width gutters would
     squeeze the article narrower than it is on a smaller screen. */
  .iw-layout--article{
    grid-template-columns:minmax(0,1fr) min(var(--article-w),100%) minmax(0,1fr);
    justify-content:center;gap:0 36px;
  }
  .iw-layout--article > #main{grid-column:2;max-width:none}
  .iw-layout--article > .iw-share-rail{grid-column:1;grid-row:1;justify-self:end;min-width:0}
  .iw-layout--article > .iw-rail{grid-column:3;min-width:0}
}

/* View header for label, archive and search pages */
.iw-hero__mark + .iw-hero__lede{margin-top:0}
.iw-viewhead{
  margin-bottom:34px;padding-bottom:26px;border-bottom:1px solid var(--line);
}
.iw-viewhead .iw-eyebrow{color:var(--accent-ink);margin-bottom:12px}
.iw-viewhead__title{
  font-family:var(--font-display);font-size:clamp(2.2rem,6vw,3.8rem);line-height:1;
  letter-spacing:-.025em;font-weight:600;text-wrap:balance;
}
.iw-viewhead__count{margin-top:12px;max-width:60ch;color:var(--ink-mute);font-size:.95rem}
.iw-viewhead__count:empty{display:none}

/* Section bar above the homepage grid */
.iw-sectionbar{display:flex;align-items:flex-end;justify-content:space-between;gap:16px;margin-bottom:22px}
.iw-sectionbar h2{font-family:var(--font-display);font-size:clamp(1.8rem,4vw,2.6rem);font-weight:600;line-height:1;letter-spacing:-.02em}
.iw-sectionbar span{color:var(--ink-mute);font-size:.82rem;font-weight:700}

.iw-empty{
  padding:56px 24px;text-align:center;border:1px dashed var(--line-2);
  border-radius:var(--radius);background:var(--surface);
}
.iw-empty h2{font-family:var(--font-display);font-size:clamp(1.6rem,4vw,2.3rem);font-weight:600;line-height:1.1;margin-bottom:10px}
.iw-empty .iw-eyebrow{color:var(--accent-ink)}
.iw-empty .iw-sidesearch{max-width:420px;margin:22px auto 0}
.iw-empty p{color:var(--ink-mute);max-width:44ch;margin-inline:auto}

/* ==========================================================================
   7. Label chips
   ========================================================================== */

.iw-chips{display:flex;flex-wrap:wrap;gap:6px;position:relative;z-index:2}
/* A card shows the two most specific topics. A heavily tagged post would
   otherwise push a two-line chip row into the title and knock the grid out of
   alignment; the post page still shows every label. */
.iw-card .iw-chips a:nth-child(n+3){display:none}
.iw-chip{
  display:inline-flex;align-items:center;gap:6px;padding:4px 11px;
  border-radius:var(--pill);border:1px solid var(--line-2);
  background:var(--surface-2);color:var(--ink-soft);
  font-size:.7rem;font-weight:700;letter-spacing:.07em;text-transform:uppercase;
  transition:background var(--dur) var(--ease),color var(--dur) var(--ease),border-color var(--dur) var(--ease);
}
.iw-chip::before{content:"";width:6px;height:6px;border-radius:2px;background:var(--topic-feature);flex:0 0 auto}
.iw-chip:hover{border-color:var(--terracotta);color:var(--ink)}

/* Colour-coded by label name, case-insensitively. Add your own by copying
   a block and changing the label text. Anything unmatched keeps the cyan. */
.iw-chip[data-label="release" i]::before,
.iw-chip[data-label="releases" i]::before,
.iw-chip[data-label="shipped" i]::before{background:var(--topic-release)}
.iw-chip[data-label="feature" i]::before,
.iw-chip[data-label="features" i]::before,
.iw-chip[data-label="product" i]::before{background:var(--topic-feature)}
.iw-chip[data-label="engineering" i]::before,
.iw-chip[data-label="platform" i]::before{background:var(--topic-engineering)}
.iw-chip[data-label="community" i]::before,
.iw-chip[data-label="governance" i]::before{background:var(--topic-community)}
.iw-chip[data-label="language" i]::before,
.iw-chip[data-label="venacula" i]::before,
.iw-chip[data-label="kasem" i]::before{background:var(--topic-language)}
.iw-filter__option[data-label="release" i]::before,
.iw-filter__option[data-label="releases" i]::before,
.iw-filter__option[data-label="shipped" i]::before{background:var(--topic-release)}
.iw-filter__option[data-label="feature" i]::before,
.iw-filter__option[data-label="features" i]::before,
.iw-filter__option[data-label="product" i]::before{background:var(--topic-feature)}
.iw-filter__option[data-label="engineering" i]::before,
.iw-filter__option[data-label="platform" i]::before{background:var(--topic-engineering)}
.iw-filter__option[data-label="community" i]::before,
.iw-filter__option[data-label="governance" i]::before{background:var(--topic-community)}
.iw-filter__option[data-label="language" i]::before,
.iw-filter__option[data-label="venacula" i]::before,
.iw-filter__option[data-label="kasem" i]::before{background:var(--topic-language)}
.iw-filter__option[data-label="mobile app" i]::before{background:var(--topic-release)}
.iw-filter__option[data-label="website" i]::before{background:var(--topic-engineering)}
.iw-filter__option[data-label="dictionary" i]::before{background:var(--topic-language)}
.iw-filter__option[data-label="tribestudio" i]::before{background:var(--topic-feature)}

/* ==========================================================================
   8. Post grid and cards
   ========================================================================== */

.iw-grid{display:grid;gap:26px;grid-template-columns:minmax(0,1fr)}
@media (min-width:640px){.iw-grid{grid-template-columns:repeat(2,minmax(0,1fr))}}
@media (min-width:1040px){.iw-grid{gap:30px}}

.iw-card{
  position:relative;display:flex;flex-direction:column;overflow:hidden;
  background:var(--surface);border:1px solid var(--line);border-radius:var(--radius);
  box-shadow:var(--shadow-1);
  transition:transform var(--dur) var(--ease),box-shadow var(--dur) var(--ease),border-color var(--dur) var(--ease);
}
.iw-card:hover{transform:translateY(-3px);box-shadow:var(--shadow-2);border-color:rgba(47,107,255,.35)}
.iw-card:focus-within{box-shadow:var(--shadow-2)}

/* Release covers are designed at 1200x630 with the headline set inside the
   art, so every slot keeps that shape. A 16:9 crop cut the words off. */
.iw-card__media{position:relative;aspect-ratio:40/21;overflow:hidden;background:var(--surface-2)}
.iw-card__media img{width:100%;height:100%;object-fit:cover;transition:transform 420ms var(--ease)}
.iw-card:hover .iw-card__media img{transform:scale(1.035)}

/* Posts with no image get a woven placeholder rather than a blank box. */
.iw-card__motif{
  display:grid;place-items:center;width:100%;height:100%;
  background-image:radial-gradient(rgba(255,255,255,.07) 1px,transparent 1px),var(--hero-bg);
  background-size:22px 22px,auto;
}
.iw-card__motif .iw-mark{width:52px;height:52px;opacity:.92}

.iw-card__body{display:flex;flex-direction:column;gap:11px;padding:20px 20px 22px;flex:1 1 auto}
.iw-card__title{font-family:var(--font-display);font-size:1.42rem;line-height:1.14;font-weight:600;letter-spacing:-.012em;text-wrap:balance}
.iw-card__title a{transition:color var(--dur) var(--ease)}
.iw-card__title a::after{content:"";position:absolute;inset:0;z-index:1}
.iw-card:hover .iw-card__title a{color:var(--link)}
.iw-card__title a:focus-visible::after{outline:3px solid var(--focus);outline-offset:-4px;border-radius:var(--radius)}
.iw-card__snippet{color:var(--ink-soft);font-size:.93rem;line-height:1.6;margin-top:-2px}
.iw-card__foot{
  display:flex;flex-wrap:wrap;align-items:center;gap:8px;margin-top:auto;padding-top:6px;
  font-size:.78rem;color:var(--ink-mute);
}
.iw-dot{opacity:.5}
.iw-card__more{
  margin-left:auto;font-weight:700;color:var(--accent-ink);
  display:inline-flex;align-items:center;gap:5px;
}
.iw-card__more::after{content:"\2192";transition:transform var(--dur) var(--ease)}
.iw-card:hover .iw-card__more::after{transform:translateX(3px)}

/* Blogger sometimes retains a Featured Post gadget while restoring a theme.
   It repeats the newest post's cover under the grid, so whenever the real
   grid has cards it is removed by CSS before first paint (no script needed).
   Only if Blog1 cannot render does it become a full-size emergency lead card
   rather than Blogger's default long excerpt with a fixed 72px thumbnail. */
.iw-layout--index:has(.iw-card) #FeaturedPost1,
.iw-layout--index:has(.iw-card) .FeaturedPost{display:none!important}
.iw-layout--index #FeaturedPost1{overflow:hidden;border:1px solid var(--line);border-radius:var(--radius);background:var(--surface);box-shadow:var(--shadow-1)}
.iw-layout--index #FeaturedPost1 .widget-content > [role="feed"]{display:block}
.iw-layout--index #FeaturedPost1 .post-content{display:grid;grid-template-columns:minmax(0,1fr)}
.iw-layout--index #FeaturedPost1 .item-thumbnail{grid-row:1;margin:0;background:var(--surface-2)}
.iw-layout--index #FeaturedPost1 .item-thumbnail a{display:block;aspect-ratio:16/9}
.iw-layout--index #FeaturedPost1 .item-thumbnail img{width:100%;height:100%;object-fit:cover}
.iw-layout--index #FeaturedPost1 .post-title{grid-row:2;padding:22px 22px 0;font-size:1.35rem;line-height:1.25;font-weight:800;letter-spacing:-.012em}
.iw-layout--index #FeaturedPost1 .item-byline{grid-row:3;padding:10px 22px 0;color:var(--ink-mute);font-size:.78rem}
.iw-layout--index #FeaturedPost1 .post-snippet{grid-row:4;padding:12px 22px 24px;color:var(--ink-soft);font-size:.93rem;line-height:1.6}
.iw-layout--index #FeaturedPost1 .snippet-item{display:-webkit-box;overflow:hidden;-webkit-box-orient:vertical;-webkit-line-clamp:4}
.iw-layout--index #FeaturedPost1 .snippet-fade{display:none}
@media (min-width:860px){
  .iw-layout--index #FeaturedPost1 .post-content{grid-template-columns:52% minmax(0,1fr);grid-template-rows:auto auto 1fr;min-height:320px}
  .iw-layout--index #FeaturedPost1 .item-thumbnail{grid-column:1;grid-row:1/4}
  .iw-layout--index #FeaturedPost1 .item-thumbnail a{height:100%;aspect-ratio:auto}
  .iw-layout--index #FeaturedPost1 .post-title{grid-column:2;grid-row:1;padding:34px 30px 0;font-size:1.6rem}
  .iw-layout--index #FeaturedPost1 .item-byline{grid-column:2;grid-row:2;padding:11px 30px 0}
  .iw-layout--index #FeaturedPost1 .post-snippet{grid-column:2;grid-row:3;padding:14px 30px 34px}
}

/* Lead card: the most recent update gets the full width and a side-by-side
   treatment once there is room for it. */
@media (min-width:640px){
  .iw-card--lead,.iw-grid > .iw-card:first-child{grid-column:1/-1}
}
@media (min-width:860px){
  .iw-card--lead,.iw-grid > .iw-card:first-child{flex-direction:row;align-items:center}
  /* The lead cover sits inset in the card at its own shape, so the art is
     never stretched or cropped to match the height of the text beside it. */
  .iw-card--lead .iw-card__media,.iw-grid > .iw-card:first-child .iw-card__media{
    flex:0 0 58%;margin:14px 0 14px 14px;border-radius:calc(var(--radius) - 6px);
  }
  .iw-card--lead .iw-card__snippet,.iw-grid > .iw-card:first-child .iw-card__snippet{
    display:-webkit-box;overflow:hidden;-webkit-box-orient:vertical;-webkit-line-clamp:3;
  }
  .iw-card--lead .iw-card__body,.iw-grid > .iw-card:first-child .iw-card__body{padding:30px 32px 32px;justify-content:center;gap:14px}
  .iw-card--lead .iw-card__title,.iw-grid > .iw-card:first-child .iw-card__title{font-size:clamp(1.6rem,2.1vw,1.95rem);line-height:1.08}
  .iw-card--lead .iw-card__snippet,.iw-grid > .iw-card:first-child .iw-card__snippet{font-size:1rem}
}

/* ==========================================================================
   9. Article
   ========================================================================== */

.iw-article__head{margin-bottom:30px}
/* A kicker of at most three topics replaces the wall of chips; the article
   footer still lists every label. */
.iw-kicker{
  display:flex;flex-wrap:wrap;align-items:center;gap:4px 10px;margin-bottom:16px;
  color:var(--accent-ink);font-size:.74rem;font-weight:800;letter-spacing:.13em;text-transform:uppercase;
}
.iw-kicker a{transition:color var(--dur) var(--ease)}
.iw-kicker a:hover{color:var(--ink)}
.iw-kicker a + a::before{content:"\00b7";margin-right:10px;color:var(--ink-mute)}
.iw-article__title{
  font-family:var(--font-display);font-size:clamp(2.3rem,6.4vw,4rem);line-height:1.02;letter-spacing:-.025em;
  font-weight:600;text-wrap:balance;
}
.iw-article__dek{
  margin-top:16px;max-width:60ch;color:var(--ink-soft);
  font-family:var(--font-body);font-size:clamp(1.05rem,2vw,1.2rem);line-height:1.6;text-wrap:pretty;
}
.iw-meta{
  display:flex;flex-wrap:wrap;align-items:center;gap:9px;margin-top:20px;
  font-size:.85rem;color:var(--ink-mute);
}
.iw-meta__mark{
  display:grid;place-items:center;width:34px;height:34px;border-radius:50%;flex:0 0 auto;background:var(--hero-bg);
}
.iw-meta__mark .iw-mark{width:20px;height:20px}
.iw-meta__author{font-weight:700;color:var(--ink)}

/* The cover is the release art at its designed 1200x630 shape. It is wider
   than the reading column on large screens, like a magazine lead image. */
.iw-cover{margin:0 0 34px;border-radius:var(--radius);overflow:hidden;border:1px solid var(--line);box-shadow:var(--shadow-2);background:var(--surface-2)}
.iw-cover img{width:100%;height:auto}
.iw-cover figcaption{padding:10px 16px 12px;background:var(--surface);color:var(--ink-mute);font-size:.8rem;line-height:1.5;text-align:center}
@media (min-width:1180px){
  .iw-layout--article .iw-cover{margin-inline:-28px}
}

/* --- Prose ------------------------------------------------------------- */

.iw-prose{
  font-family:var(--font-body);font-size:var(--fs-body);line-height:1.75;
  color:var(--ink);
}
/* Release posts wrap their body in one article element (and Blogger's editor
   sometimes in one div), so the vertical rhythm has to reach through that
   single wrapper or every paragraph sits flush against the next. */
.iw-prose > * + *,
.iw-prose > :is(article,div):only-child > * + *{margin-top:1.15em}
.iw-prose p{text-wrap:pretty}

/* The theme already shows the post's first image as the cover. Release posts
   also open with that same cover so Blogger can pick it as the share image;
   hide the body copy before first paint. The script removes it for good,
   including figure versions, and moves any caption onto the cover. */
.iw-article.has-cover .iw-prose > .separator:first-child,
.iw-article.has-cover .iw-prose > :is(article,div):only-child > .separator:first-child,
.iw-article.has-cover .iw-prose > p:first-child:has(> img:only-child),
.iw-article.has-cover .iw-prose > p:first-child:has(> a:only-child > img:only-child),
.iw-article.has-cover .iw-prose > :is(article,div):only-child > p:first-child:has(> img:only-child),
.iw-article.has-cover .iw-prose > :is(article,div):only-child > p:first-child:has(> a:only-child > img:only-child){display:none}
.iw-prose a{
  color:var(--link);text-decoration:underline;
  text-decoration-color:rgba(47,107,255,.45);text-decoration-thickness:2px;text-underline-offset:3px;
  transition:color var(--dur) var(--ease),text-decoration-color var(--dur) var(--ease);
}
.iw-prose a:hover{color:var(--link-hover);text-decoration-color:currentColor}

.iw-prose h2,.iw-prose h3,.iw-prose h4,.iw-prose h5,.iw-prose h6{
  font-family:var(--font-ui);font-weight:800;letter-spacing:-.015em;
  line-height:1.22;text-wrap:balance;scroll-margin-top:96px;
}
.iw-prose h2,.iw-prose h3{font-family:var(--font-display);font-weight:600;letter-spacing:-.02em;line-height:1.12}
.iw-prose h2{font-size:1.85em;margin-top:2em;padding-top:.15em}
.iw-prose h2::after{
  content:"";display:block;width:46px;height:3px;border-radius:2px;
  margin-top:.42em;background:linear-gradient(90deg,var(--gold),var(--terracotta));
}
.iw-prose h3{font-size:1.4em;margin-top:1.8em}
.iw-prose h4{font-size:1.05em;margin-top:1.6em;color:var(--ink-soft)}
.iw-prose h5,.iw-prose h6{font-size:1em;margin-top:1.5em;color:var(--ink-soft)}
.iw-prose dd{margin-left:1.35em}
.iw-prose dt{font-weight:700}
.iw-prose dd + dt{margin-top:1em}

.iw-prose ul,.iw-prose ol{padding-left:1.35em}
.iw-prose li{list-style:inherit;margin-top:.42em}
.iw-prose ul{list-style:none;padding-left:1.5em}
.iw-prose ul > li{position:relative}
.iw-prose ul > li::before{
  content:"";position:absolute;left:-1.15em;top:.72em;
  width:7px;height:7px;border-radius:2px;background:var(--terracotta);
}
.iw-prose ol{list-style:decimal}
.iw-prose ol > li::marker{color:var(--accent-ink);font-weight:700}
.iw-prose li > ul,.iw-prose li > ol{margin-top:.42em}

.iw-prose blockquote{
  margin-inline:0;padding:.2em 0 .2em 1em;border-left:4px solid var(--terracotta);
  font-family:var(--font-display);font-size:1.45em;font-weight:500;line-height:1.3;color:var(--ink);
}
.iw-prose blockquote p + p{margin-top:.8em}

/* Release images carry width and height, so they reserve their space; the
   tint shows where a lazy image is still on its way instead of a white hole. */
.iw-prose img{border-radius:var(--radius-sm);box-shadow:var(--shadow-1);margin-inline:auto;background:var(--surface-2)}
.iw-prose figure{margin-block:1.6em}
.iw-prose figcaption,.iw-prose .separator + br{font-family:var(--font-ui)}
.iw-prose figcaption{
  margin-top:.7em;text-align:center;font-size:.83rem;color:var(--ink-mute);
}
/* Blogger wraps pasted images in .separator */
.iw-prose .separator{margin:1.6em 0!important;clear:both;text-align:center}
.iw-prose .separator a{display:inline-block;margin:0!important}

.iw-prose code{
  font-family:var(--font-mono);font-size:.86em;
  padding:.16em .42em;border-radius:5px;
  background:var(--surface-2);border:1px solid var(--line);
  color:var(--code-ink);overflow-wrap:anywhere;
}
.iw-prose pre{
  --focus:var(--gold-soft);
  position:relative;overflow-x:auto;padding:54px 22px 20px;
  border-radius:var(--radius-sm);background:var(--code-bg);color:var(--code-fg);
  font-family:var(--font-mono);font-size:.86rem;line-height:1.62;
  border:1px solid rgba(255,255,255,.08);
}
.iw-prose pre code{background:none;border:0;padding:0;color:inherit;font-size:1em;overflow-wrap:normal}
.iw-copy{
  position:absolute;top:10px;right:10px;padding:5px 11px;border-radius:var(--pill);
  border:1px solid rgba(255,255,255,.22);background:rgba(255,255,255,.09);
  color:#fff;font-family:var(--font-ui);font-size:.7rem;font-weight:700;
  letter-spacing:.06em;text-transform:uppercase;opacity:1;
  transition:opacity var(--dur) var(--ease),background var(--dur) var(--ease);
}
.iw-prose pre:hover .iw-copy,.iw-copy:focus-visible{opacity:1}
.iw-copy:hover{background:rgba(255,255,255,.18)}

.iw-tablewrap{overflow-x:auto;border:1px solid var(--line);border-radius:var(--radius-sm)}
.iw-prose caption{padding:12px 15px;text-align:left;color:var(--ink-soft)}
.iw-prose table{width:100%;font-family:var(--font-ui);font-size:.9rem;min-width:480px}
.iw-prose th,.iw-prose td{padding:11px 15px;text-align:left;border-bottom:1px solid var(--line)}
.iw-prose thead th{
  background:var(--surface-2);font-weight:700;font-size:.76rem;
  letter-spacing:.07em;text-transform:uppercase;color:var(--ink-soft);
}
.iw-prose tbody tr:last-child td{border-bottom:0}

.iw-prose hr{
  border:0;height:22px;margin-block:2.2em;
  background-image:radial-gradient(circle,var(--terracotta) 2.5px,transparent 2.6px);
  background-size:22px 22px;background-position:center;background-repeat:repeat-x;
  -webkit-mask-image:linear-gradient(90deg,transparent,#000 42%,#000 58%,transparent);
  mask-image:linear-gradient(90deg,transparent,#000 42%,#000 58%,transparent);
}

.iw-prose iframe{width:100%;aspect-ratio:16/9;height:auto;border:0;border-radius:var(--radius-sm)}

/* --- Editor helper classes --------------------------------------------
   Paste these into a post's HTML view to get consistent components.
   Documented in apps/updates-blog/README.md                            */

.iw-lede{font-size:1.16em;line-height:1.62;color:var(--ink-soft)}

.iw-note,.iw-tip,.iw-warn,.iw-ship{
  font-family:var(--font-ui);font-size:.95rem;line-height:1.6;
  padding:16px 18px;border-radius:var(--radius-sm);
  border:1px solid var(--line);border-left-width:3px;background:var(--callout-bg);
}
.iw-note{border-left-color:var(--info-ink)}
.iw-tip{border-left-color:var(--gold)}
.iw-warn{border-left-color:var(--warn-ink)}
.iw-ship{border-left-color:var(--success-ink)}
.iw-note > strong:first-child,.iw-tip > strong:first-child,
.iw-warn > strong:first-child,.iw-ship > strong:first-child{
  display:block;margin-bottom:5px;font-size:.74rem;
  letter-spacing:.09em;text-transform:uppercase;
}
.iw-note > strong:first-child{color:var(--info-ink)}
.iw-tip > strong:first-child{color:var(--accent-ink)}
.iw-warn > strong:first-child{color:var(--warn-ink)}
.iw-ship > strong:first-child{color:var(--success-ink)}
.iw-note > * + *,.iw-tip > * + *,.iw-warn > * + *,.iw-ship > * + *{margin-top:.7em}

.iw-kbd{
  font-family:var(--font-mono);font-size:.78em;padding:.16em .5em;
  border-radius:5px;border:1px solid var(--line-2);border-bottom-width:2px;
  background:var(--surface);color:var(--ink);
}
.iw-cols{display:grid;gap:18px;grid-template-columns:minmax(0,1fr)}
@media (min-width:640px){.iw-cols{grid-template-columns:repeat(2,minmax(0,1fr))}}

/* ==========================================================================
   10. Article footer: labels, share, author, pager, related
   ========================================================================== */

.iw-postfoot{margin-top:40px;padding-top:26px;border-top:1px solid var(--line)}
.iw-postfoot__row{display:flex;flex-wrap:wrap;align-items:center;gap:16px;justify-content:space-between}
.iw-share{display:flex;flex-wrap:wrap;align-items:center;gap:7px}
.iw-share__label{font-size:.72rem;font-weight:700;letter-spacing:.09em;text-transform:uppercase;color:var(--ink-mute)}
/* Named share buttons: a reader should not have to decode four bare icons. */
.iw-share button,.iw-share a{
  display:inline-flex;align-items:center;gap:7px;min-height:36px;padding:7px 13px 7px 11px;border-radius:var(--pill);
  border:1px solid var(--line-2);background:var(--surface);color:var(--ink-soft);
  font-size:.78rem;font-weight:700;white-space:nowrap;
  transition:background var(--dur) var(--ease),color var(--dur) var(--ease),border-color var(--dur) var(--ease),transform var(--dur) var(--ease);
}
.iw-share button:hover,.iw-share a:hover{
  background:var(--action-bg);border-color:var(--action-bg);color:var(--action-ink);transform:translateY(-2px);
}
.iw-share svg{width:16px;height:16px;flex:0 0 auto;fill:none;stroke:currentColor;stroke-width:1.9;stroke-linecap:round;stroke-linejoin:round}
.iw-share .is-copied,.iw-share .is-copied:hover{background:var(--success-bg);border-color:var(--success-bg);color:#fff}

/* Follow card after the article */
.iw-follow{
  --focus:var(--gold-soft);
  position:relative;isolation:isolate;overflow:hidden;margin-top:34px;padding:28px;
  border-radius:var(--radius);background:var(--hero-bg);color:var(--on-dark);
}
.iw-follow::after{content:"";position:absolute;inset:0;z-index:-1;opacity:.12;background-image:var(--dots);background-size:22px 22px}
.iw-follow h2{font-family:var(--font-display);font-size:clamp(1.5rem,3.4vw,2rem);font-weight:600;line-height:1.1;color:#fff}
.iw-follow p{margin-top:8px;max-width:52ch;color:rgba(255,255,255,.78);font-size:.95rem;line-height:1.6}
.iw-follow .iw-hero__actions{margin-top:18px}

.iw-author{
  display:flex;gap:16px;align-items:flex-start;margin-top:30px;padding:22px;
  border:1px solid var(--line);border-radius:var(--radius);background:var(--surface);
}
.iw-author > div{min-width:0}
.iw-author img{width:52px;height:52px;border-radius:50%;object-fit:cover;flex:0 0 auto}
.iw-author__mark{
  display:grid;place-items:center;width:52px;height:52px;border-radius:50%;flex:0 0 auto;
  background:var(--hero-bg);
}
.iw-author__mark .iw-mark{width:30px;height:30px}
.iw-author__name{font-family:var(--font-display);font-weight:600;font-size:1.3rem;line-height:1.1}
.iw-author__role{margin-top:3px;font-size:.87rem;color:var(--ink-mute);line-height:1.55}

.iw-pager{display:grid;gap:12px;margin-top:34px;grid-template-columns:minmax(0,1fr)}
@media (min-width:640px){.iw-pager{grid-template-columns:repeat(2,minmax(0,1fr))}}
.iw-pager__link{
  display:flex;flex-direction:column;gap:4px;padding:16px 20px;
  border:1px solid var(--line);border-radius:var(--radius);background:var(--surface);
  transition:border-color var(--dur) var(--ease),transform var(--dur) var(--ease),box-shadow var(--dur) var(--ease);
}
.iw-pager__link:hover{border-color:rgba(47,107,255,.35);transform:translateY(-2px);box-shadow:var(--shadow-1)}
.iw-pager__link--next{text-align:right;grid-column:-2/-1}
.iw-pager__kicker{font-size:.7rem;font-weight:700;letter-spacing:.1em;text-transform:uppercase;color:var(--accent-ink)}
.iw-pager__title{font-weight:700;font-size:.95rem;color:var(--ink)}

.iw-related{margin-top:44px;padding-top:30px;border-top:1px solid var(--line)}
.iw-related[hidden]{display:none}
.iw-related h2{
  font-size:.76rem;font-weight:700;letter-spacing:.12em;text-transform:uppercase;
  color:var(--ink-mute);margin-bottom:18px;
}
/* Related updates are small cards with their release covers, not 64px
   squares that shrink the designed art to an unreadable crop. */
.iw-related__list{display:grid;gap:18px;grid-template-columns:minmax(0,1fr)}
@media (min-width:560px){.iw-related__list{grid-template-columns:repeat(3,minmax(0,1fr))}}
.iw-related__item{
  display:flex;flex-direction:column;overflow:hidden;min-width:0;
  border:1px solid var(--line);border-radius:var(--radius-sm);background:var(--surface);
  transition:border-color var(--dur) var(--ease),transform var(--dur) var(--ease),box-shadow var(--dur) var(--ease);
}
.iw-related__item:hover{border-color:rgba(47,107,255,.35);transform:translateY(-2px);box-shadow:var(--shadow-1)}
.iw-related__thumb{
  display:block;width:100%;height:auto;aspect-ratio:40/21;object-fit:cover;background:var(--surface-2);
}
.iw-related__text{min-width:0;display:block;padding:12px 14px 14px}
.iw-related__t{display:block;font-family:var(--font-display);font-weight:600;font-size:1.06rem;line-height:1.22}
.iw-related__d{display:block;margin-top:6px;font-size:.76rem;color:var(--ink-mute)}
.iw-related__motif{
  width:100%;aspect-ratio:40/21;display:grid;place-items:center;background:var(--hero-bg);
}
.iw-related__motif .iw-mark{width:40px;height:40px}

/* Table of contents rail, built from the article's own headings. */
.iw-rail{position:sticky;top:calc(var(--head-h) + 22px);max-height:calc(100vh - var(--head-h) - 44px);overflow-y:auto}
.iw-rail[hidden]{display:none}
.iw-share-rail{position:sticky;top:calc(var(--head-h) + 22px)}
.iw-share-rail[hidden]{display:none}
.iw-share-rail .iw-share{flex-direction:column;align-items:stretch;width:150px;gap:8px}
.iw-share-rail .iw-share__label{margin-bottom:4px}
.iw-share-rail .iw-share a,.iw-share-rail .iw-share button{justify-content:flex-start}
@media (max-width:1179px){
  .iw-layout--article .iw-rail{
    position:static;max-height:none;max-width:var(--article-w);width:100%;margin:0 auto 26px;
    border:1px solid var(--line);border-radius:var(--radius-sm);background:var(--surface);
  }
  .iw-layout--article .iw-rail .iw-toc__title{margin:0;padding:15px 20px;cursor:pointer}
  .iw-layout--article .iw-rail .iw-toc__list{margin:0 20px 18px}
}
/* On small screens the contents fold into one line, so the cover leads
   straight into the prose instead of a five-row list between them. */
.iw-toc details > summary{list-style:none;display:flex;align-items:center;gap:8px}
.iw-toc details > summary::-webkit-details-marker{display:none}
.iw-toc details > summary::after{content:"\2304";margin-left:auto;transition:transform var(--dur) var(--ease)}
.iw-toc details[open] > summary::after{transform:rotate(180deg)}
.iw-toc__count{color:var(--ink-mute);font-weight:600;letter-spacing:.04em;text-transform:none}
@media (min-width:1180px){
  .iw-toc details > summary{pointer-events:none}
  .iw-toc details > summary::after,.iw-toc__count{display:none}
}
.iw-toc__title{
  font-size:.7rem;font-weight:700;letter-spacing:.12em;text-transform:uppercase;
  color:var(--ink-mute);margin-bottom:12px;
}
.iw-toc__list{border-left:2px solid var(--line);display:flex;flex-direction:column}
.iw-toc__list a{
  padding:6px 0 6px 14px;margin-left:-2px;border-left:2px solid transparent;
  font-size:.83rem;line-height:1.45;color:var(--ink-mute);
  transition:color var(--dur) var(--ease),border-color var(--dur) var(--ease);
}
.iw-toc__list a:hover{color:var(--ink)}
.iw-toc__list a.is-active{color:var(--ink);border-left-color:var(--terracotta);font-weight:700}
.iw-toc__list a[data-depth="3"]{padding-left:26px;font-size:.79rem}

/* ==========================================================================
   11. Comments (Blogger's own markup, restyled)
   ========================================================================== */

.iw-comments{margin-top:48px;padding-top:32px;border-top:1px solid var(--line)}
/* Blogger's comment iframe, reCAPTCHA and scripts load only once a reader
   opens the discussion, so a post page stays light. */
.iw-comments__gate{border:1px solid var(--line);border-radius:var(--radius-sm);background:var(--surface)}
.iw-comments__gate > summary{
  display:flex;align-items:center;gap:12px;flex-wrap:wrap;min-height:56px;padding:15px 20px;
  cursor:pointer;list-style:none;font-weight:800;color:var(--ink);
}
.iw-comments__gate > summary::-webkit-details-marker{display:none}
.iw-comments__gate > summary::after{content:"\2304";margin-left:auto;color:var(--accent-ink);transition:transform var(--dur) var(--ease)}
.iw-comments__gate[open] > summary{border-bottom:1px solid var(--line)}
.iw-comments__gate[open] > summary::after{transform:rotate(180deg)}
.iw-comments__hint{color:var(--ink-mute);font-size:.78rem;font-weight:600}
.iw-comments__mount{padding:20px}
.iw-comments h3,.iw-comments h4,.iw-comments .comments h4{
  font-size:1.1rem;font-weight:800;margin-bottom:18px;
}
.iw-comments .comments{color:var(--ink)}
.iw-comments .comments .comment{
  padding:16px 18px;margin-bottom:12px;
  border:1px solid var(--line);border-radius:var(--radius-sm);background:var(--surface);
}
.iw-comments .comments .comment > .comment-block{min-width:0}
.iw-comments .comments .comment-block{padding:0;margin:0}
.iw-comments .comments .comment-header a{color:var(--link)}
.iw-comments .comments .comment-content a{color:var(--link);text-decoration:underline;text-underline-offset:3px}
.iw-comments .comments .comment-header{display:flex;flex-wrap:wrap;gap:8px;align-items:baseline}
.iw-comments .comments cite,.iw-comments .comments .user{font-style:normal;font-weight:700}
.iw-comments .comments .datetime,.iw-comments .comments .comment-timestamp{
  font-size:.78rem;color:var(--ink-mute)
}
.iw-comments .comments .comment-content{margin-top:8px;font-size:.94rem;line-height:1.65;color:var(--ink-soft)}
.iw-comments .comments .comment-actions a,
.iw-comments .comments .comment-reply,
.iw-comments .comments .continue a{
  display:inline-block;margin-top:9px;margin-right:10px;
  font-size:.78rem;font-weight:700;color:var(--accent-ink);
}
.iw-comments .comments .comment-replies{margin-left:20px;padding-left:14px;border-left:2px solid var(--line)}
.iw-comments .comments .avatar-image-container img{border-radius:50%}
.iw-comments .comments .comment-thread ol{padding-left:0}
.iw-comments .comments .thread-toggle{font-size:.8rem}
.iw-comments #comment-editor{width:100%;border:1px solid var(--line);border-radius:var(--radius-sm);background:var(--surface)}
.iw-comments .comment-form h4{margin-top:26px}
.iw-comments .comments .footer{margin-top:14px;font-size:.82rem;color:var(--ink-mute)}
.iw-comments .comments .loadmore{margin-top:12px}
.iw-comments .comments .loadmore.hidden,.iw-comments .comments .hidden{display:none}

/* ==========================================================================
   12. Sidebar widgets
   ========================================================================== */

.iw-side__in{display:flex;flex-direction:column;gap:24px;position:sticky;top:calc(var(--head-h) + 22px)}
.iw-side .widget{
  padding:20px;border:1px solid var(--line);border-radius:var(--radius);
  background:var(--surface);box-shadow:var(--shadow-1);
}
.iw-side .widget h2,.iw-side .widget h3,.iw-side .widget .title,.iw-widget-title{
  display:block;margin-bottom:14px;padding-bottom:11px;
  border-bottom:1px solid var(--line);
  font-size:.72rem;font-weight:700;letter-spacing:.12em;text-transform:uppercase;
  color:var(--ink-mute);
}
.iw-side .widget-content{font-size:.92rem;color:var(--ink-soft);line-height:1.6}
.iw-side .widget-content a{color:var(--link);transition:color var(--dur) var(--ease)}
.iw-side .widget-content a:hover{color:var(--link-hover)}
.iw-side .widget-content .iw-chip{color:var(--ink-soft)}
.iw-side .widget-content .iw-chip:hover{color:var(--ink)}

/* Labels */
.iw-labels{display:flex;flex-wrap:wrap;gap:7px}
.iw-labels__count{color:var(--ink-mute);font-size:.68rem}
/* The blog has dozens of labels. The sidebar shows the busiest topics and
   keeps the rest one click away rather than a sixty-chip wall. */
.iw-labels.is-trimmed .iw-chip.is-extra{display:none}
.iw-labels__more{
  display:inline-flex;align-items:center;min-height:30px;padding:4px 12px;margin-top:4px;border-radius:var(--pill);
  border:1px dashed var(--line-2);color:var(--accent-ink);font-size:.74rem;font-weight:800;
}
.iw-labels__more:hover{border-style:solid;border-color:var(--terracotta)}

/* Popular posts */
.iw-pp{display:flex;flex-direction:column;gap:14px}
.iw-pp__item{display:flex;gap:12px;align-items:center}
.iw-pp__item img{width:56px;height:56px;flex:0 0 auto;border-radius:8px;object-fit:cover;background:var(--surface-2)}
.iw-pp__n{
  display:grid;place-items:center;width:56px;height:56px;flex:0 0 auto;border-radius:8px;
  background:var(--surface-2);color:var(--ink-mute);font-weight:800;font-size:1.1rem;
}
.iw-pp__t{font-weight:700;font-size:.9rem;line-height:1.38;color:var(--ink)}
.iw-pp__item:hover .iw-pp__t{color:var(--accent-ink)}

/* Archive (Blogger's default markup) */
.iw-side .BlogArchive ul,.iw-side .BlogArchive #ArchiveList ul{display:flex;flex-direction:column;gap:2px}
.iw-side .BlogArchive li{font-size:.9rem}
.iw-side .BlogArchive li a{display:inline-block;padding:5px 0}
.iw-side .BlogArchive select{
  width:100%;padding:10px 12px;border-radius:var(--radius-sm);
  border:1px solid var(--control-border);background:var(--surface-2);
}
.iw-side .BlogArchive .toggle{margin-right:6px;color:var(--ink-mute)}
/* Blogger writes the month and its count with no space between them
   ("October27"); give the count its own quiet pill. */
.iw-side .BlogArchive li a{display:flex;align-items:center;gap:8px}
.iw-side .BlogArchive .post-count{
  margin-left:auto;min-width:26px;padding:1px 8px;border-radius:var(--pill);
  background:var(--surface-2);color:var(--ink-mute);font-size:.72rem;font-weight:700;text-align:center;
  font-variant-numeric:tabular-nums;
}

/* Search widget */
.iw-sidesearch{display:flex;gap:7px}
.iw-sidesearch input{
  flex:1 1 auto;min-width:0;padding:10px 13px;font-size:.9rem;
  border-radius:var(--radius-sm);border:1px solid var(--control-border);
  background:var(--surface-2);color:var(--ink);
}
.iw-sidesearch input::placeholder{color:var(--ink-mute);opacity:1}
.iw-sidesearch input:focus{outline:none;border-color:var(--focus)}
.iw-sidesearch button{
  flex:0 0 auto;padding:10px 14px;border-radius:var(--radius-sm);
  background:var(--action-bg);color:var(--action-ink);font-size:.85rem;font-weight:700;
}
.iw-sidesearch button:hover{filter:brightness(1.1)}

/* Profile widget */
.iw-side .Profile .profile-img{border-radius:50%;margin:0 12px 8px 0}
.iw-side .Profile .profile-datablock{margin-bottom:8px}
.iw-profile{display:flex;align-items:center;gap:12px;font-weight:600}
.iw-profile__img{width:42px;height:42px;border-radius:50%;object-fit:cover}

/* Report Abuse. Blogger adds this widget to every blog; it sits quietly at the
   end of the sidebar rather than as a heading in the middle of the reading
   column, which is where Blogger puts it when a theme does not claim it. */
.iw-side .ReportAbuse{padding:0;border:0;background:none;box-shadow:none}
.iw-reportabuse{font-size:.78rem;color:var(--ink-mute)}
.iw-reportabuse a{color:var(--ink-mute);text-decoration:underline;text-underline-offset:2px}
.iw-reportabuse a:hover{color:var(--accent-ink)}

/* ==========================================================================
   13. Footer
   ========================================================================== */

.iw-foot{
  --focus:var(--gold-soft);
  position:relative;isolation:isolate;overflow:hidden;margin-top:auto;
  background:
    radial-gradient(circle at 92% 0,rgba(47,107,255,.28),transparent 30rem),
    linear-gradient(145deg,#0b1225,#0f1830 55%,#162a64);
  color:rgba(255,255,255,.72);
  padding:52px 0 22px;
}
.iw-foot::before,.iw-foot::after{content:"";position:absolute;z-index:0;pointer-events:none}
.iw-foot::before{
  width:320px;aspect-ratio:1;top:-194px;right:-184px;
  border:1px solid rgba(142,180,255,.12);border-radius:50%;
  box-shadow:
    0 0 0 42px rgba(47,107,255,.025),
    0 0 0 84px rgba(34,211,238,.02),
    0 0 0 126px rgba(255,255,255,.018);
}
.iw-foot::after{
  width:300px;aspect-ratio:1;bottom:-164px;left:-174px;opacity:.28;
  background-image:
    repeating-linear-gradient(45deg,transparent 0 15px,rgba(255,255,255,.12) 15px 17px,transparent 17px 32px),
    repeating-linear-gradient(-45deg,transparent 0 15px,rgba(142,180,255,.1) 15px 17px,transparent 17px 32px);
  -webkit-mask-image:radial-gradient(circle,#000 0 28%,transparent 72%);
  mask-image:radial-gradient(circle,#000 0 28%,transparent 72%);
}
.iw-foot > .iw-shell{position:relative;z-index:1}
.iw-foot__top{display:grid;gap:34px;margin-bottom:34px}
@media (min-width:900px){.iw-foot__top{grid-template-columns:1.4fr 2fr;gap:60px}}
.iw-foot__brand p{margin-top:12px;max-width:42ch;font-size:.9rem;color:rgba(255,255,255,.6);line-height:1.62}
.iw-foot__cols{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:24px}
@media (min-width:640px){.iw-foot__cols{grid-template-columns:repeat(3,minmax(0,1fr))}}
.iw-foot .widget{min-width:0}
.iw-foot .widget h2,.iw-foot .widget h3,.iw-foot .widget .title,.iw-foot .iw-widget-title{
  display:block;margin-bottom:12px;padding-bottom:0;border-bottom:0;color:#fff;
  font-size:.74rem;font-weight:700;letter-spacing:.1em;text-transform:uppercase;
}
.iw-foot .widget-content{font-size:.89rem;line-height:1.6;color:rgba(255,255,255,.62)}
.iw-foot .widget-content ul{display:flex;flex-direction:column;gap:9px}
.iw-foot .widget-content a{color:rgba(255,255,255,.65);transition:color var(--dur) var(--ease)}
.iw-foot .widget-content a:hover{color:var(--blue-line)}
.iw-foot__bottom{
  display:flex;flex-direction:column;gap:7px;padding-top:22px;
  border-top:1px solid rgba(255,255,255,.1);font-size:.8rem;color:rgba(255,255,255,.55);
}
@media (min-width:900px){.iw-foot__bottom{flex-direction:row;justify-content:space-between;align-items:center}}
.iw-foot__bottom a{color:rgba(255,255,255,.72)}
.iw-foot__bottom a:hover{color:var(--blue-line)}

/* ==========================================================================
   14. Back to top, motion, print
   ========================================================================== */

.iw-top{
  position:fixed;z-index:70;right:18px;bottom:18px;
  display:grid;place-items:center;width:44px;height:44px;border-radius:50%;
  border:1px solid var(--line-2);background:var(--surface);color:var(--ink);
  box-shadow:var(--shadow-2);
  opacity:0;visibility:hidden;transform:translateY(10px);
  transition:opacity var(--dur) var(--ease),transform var(--dur) var(--ease),visibility var(--dur);
}
.iw-top.is-on{opacity:1;visibility:visible;transform:none}
.iw-top:hover{background:var(--action-bg);border-color:var(--action-bg);color:var(--action-ink)}
.iw-top svg{width:18px;height:18px;fill:none;stroke:currentColor;stroke-width:2.2;stroke-linecap:round;stroke-linejoin:round}

body{display:flex;flex-direction:column;min-height:100vh}
.iw-main{flex:1 0 auto}

/* Blogger's own navbar. The widget is declared so Layout keeps working, but the
   theme supplies its own header, so the injected iframe is taken out of the
   page. Without this it reserves an iframe's default 150px and leaves an empty
   band above the header - Blogger's stylesheet that would size it is disabled
   by b:css='false'. */
#navbar,#navbar-iframe,#navbar-iframe-container{
  display:none!important;height:0!important;visibility:hidden!important;
}

/* Any widget Blogger adds to the post column on its own - Report Abuse and the
   profile box are added to every new blog - is placed in the sidebar by this
   theme. If one still lands here, give it the same card as the sidebar rather
   than letting it render unstyled. */
#main > .widget:not(.Blog){
  margin-top:24px;padding:20px;
  border:1px solid var(--line);border-radius:var(--radius);
  background:var(--surface);font-size:.92rem;color:var(--ink-soft);
}
#main > .widget:not(.Blog) h2,#main > .widget:not(.Blog) h3{
  margin-bottom:10px;font-size:.72rem;font-weight:700;letter-spacing:.12em;
  text-transform:uppercase;color:var(--ink-mute);
}
#main > .widget:not(.Blog) a{color:var(--accent-ink)}
#main > .widget:not(.Blog) img{border-radius:8px}

/* Visible keyboard focus. Late in the cascade so it beats the outline:none on
   the two search inputs; :focus-visible keeps it off mouse clicks. */
a:focus-visible,button:focus-visible,input:focus-visible,
textarea:focus-visible,select:focus-visible,summary:focus-visible,
[tabindex]:focus-visible{
  outline:2px solid var(--focus);outline-offset:3px;border-radius:4px;
}
.iw-searchform input:focus-visible,.iw-sidesearch input:focus-visible{outline-offset:1px}

@media (prefers-reduced-motion:reduce){
  html{scroll-behavior:auto}
  *,*::before,*::after{
    animation-duration:.001ms!important;animation-iteration-count:1!important;
    transition-duration:.001ms!important;
  }
}

@media print{
  .iw-head,.iw-searchpane,.iw-side,.iw-rail,.iw-top,.iw-progress,
  .iw-share,.iw-share-rail,.iw-pager,.iw-related,.iw-comments,.iw-foot,.iw-hero,.iw-follow{display:none!important}
  :root,:root[data-theme],:root:not([data-theme]){
    color-scheme:light;--bg:#fff;--bg-alt:#fff;--surface:#fff;--surface-2:#f3f3f3;
    --ink:#000;--ink-soft:#333;--ink-mute:#444;--line:#ccc;--line-2:#aaa;
    --link:#000;--link-hover:#000;--accent-ink:#444;--code-ink:#000;
    --info-ink:#333;--success-ink:#333;--warn-ink:#333;
    --code-bg:#f3f3f3;--code-fg:#000;--shadow-1:none;--shadow-2:none;
    --callout-bg:#f3f3f3;
  }
  body{min-width:0;background:#fff;color:#000}
  .iw-layout--article{display:block}
  .iw-layout--article > #main{max-width:100%}
  .iw-main{padding-block:0}
  .iw-prose a{text-decoration:underline}
  .iw-prose pre{padding:16px;white-space:pre-wrap}
  .iw-copy{display:none}
  .iw-tablewrap{overflow:visible}
  .iw-prose table{min-width:0;table-layout:fixed}
  .iw-prose th,.iw-prose td{overflow-wrap:anywhere}
  .iw-prose h2,.iw-prose h3{break-after:avoid}
}

body.script:
//
(function () {
  'use strict';

  var doc = document;
  var root = doc.documentElement;
  var qs = function (sel, ctx) { return (ctx || doc).querySelector(sel); };
  var qsa = function (sel, ctx) { return Array.prototype.slice.call((ctx || doc).querySelectorAll(sel)); };
  var reduceMotion = window.matchMedia('(prefers-reduced-motion: reduce)').matches;

  /* ---- Footer year ---------------------------------------------------- */
  var yearEl = qs('#iw-year');
  if (yearEl) { yearEl.textContent = String(new Date().getFullYear()); }

  /* ---- Colour scheme -------------------------------------------------- */
  var themeBtn = qs('#iw-theme-btn');
  var preferredTheme = window.matchMedia('(prefers-color-scheme: dark)');
  function currentTheme() {
    var set = root.getAttribute('data-theme');
    if (set === 'dark' || set === 'light') { return set; }
    return preferredTheme.matches ? 'dark' : 'light';
  }
  function syncThemeBtn() {
    if (!themeBtn) { return; }
    var dark = currentTheme() === 'dark';
    themeBtn.setAttribute('aria-pressed', dark ? 'true' : 'false');
    themeBtn.title = dark ? 'Switch to light' : 'Switch to dark';
  }
  if (themeBtn) {
    themeBtn.addEventListener('click', function () {
      var next = currentTheme() === 'dark' ? 'light' : 'dark';
      root.setAttribute('data-theme', next);
      try { localStorage.setItem('iw-theme', next); } catch (e) {}
      syncThemeBtn();
    });
    syncThemeBtn();
  }
  if (preferredTheme.addEventListener) {
    preferredTheme.addEventListener('change', syncThemeBtn);
  }

  // Keep sticky search and the reading rail below the actual header, even
  // when a customised blog title or an expanded mobile menu makes it taller.
  var header = qs('#iw-head');
  if (header && 'ResizeObserver' in window) {
    new ResizeObserver(function () {
      root.style.setProperty('--head-h', header.getBoundingClientRect().height + 'px');
    }).observe(header);
  }

  /* ---- Navigation ----------------------------------------------------- */
  var nav = qs('#iw-nav');
  var menuBtn = qs('#iw-menu-btn');
  if (nav && menuBtn) {
    // The nav is only collapsible below the breakpoint that shows the menu
    // button; above it the nav is always laid out, so it must never be inert.
    var collapsible = window.matchMedia('(max-width: 979px)');

    function setNavState(open) {
      nav.classList.toggle('is-open', open);
      menuBtn.setAttribute('aria-expanded', open ? 'true' : 'false');
      syncNavHidden();
    }
    function syncNavHidden() {
      var hidden = collapsible.matches && !nav.classList.contains('is-open');
      if (hidden && nav.contains(doc.activeElement)) { menuBtn.focus(); }
      nav.setAttribute('aria-hidden', hidden ? 'true' : 'false');
      if (hidden) { nav.setAttribute('inert', ''); } else { nav.removeAttribute('inert'); }
    }

    menuBtn.addEventListener('click', function () {
      setNavState(!nav.classList.contains('is-open'));
    });
    doc.addEventListener('keydown', function (ev) {
      if (ev.key === 'Escape' && nav.classList.contains('is-open')) {
        setNavState(false);
        menuBtn.focus();
      }
    });
    if (collapsible.addEventListener) {
      collapsible.addEventListener('change', function () {
        if (!collapsible.matches) { nav.classList.remove('is-open'); menuBtn.setAttribute('aria-expanded', 'false'); }
        syncNavHidden();
      });
    }
    syncNavHidden();
  }

  // Mark the nav item matching the current page.
  var here = location.pathname.replace(/\/+$/, '') || '/';
  qsa('.iw-navlist a').forEach(function (a) {
    var raw = a.getAttribute('href') || '';
    if (raw.charAt(0) === '#' || a.origin !== location.origin) { return; }
    var path = a.pathname.replace(/\/+$/, '') || '/';
    if (path === here) {
      var li = a.closest('li');
      if (li) { li.classList.add('is-current'); }
      a.setAttribute('aria-current', 'page');
    }
  });

  // Close the topic filter when focus moves elsewhere or Escape is pressed.
  var filter = qs('#iw-filter');
  if (filter) {
    doc.addEventListener('click', function (event) {
      if (filter.open && !filter.contains(event.target)) { filter.removeAttribute('open'); }
    });
    filter.addEventListener('keydown', function (event) {
      if (event.key === 'Escape') {
        filter.removeAttribute('open');
        var summary = qs('summary', filter);
        if (summary) { summary.focus(); }
      }
    });
  }

  /* ---- Search panel --------------------------------------------------- */
  var searchBtn = qs('#iw-search-btn');
  var searchPane = qs('#iw-searchpane');
  if (searchBtn && searchPane) {
    var searchReturnFocus = null;
    function closeSearch() {
      searchPane.setAttribute('hidden', 'hidden');
      searchBtn.setAttribute('aria-expanded', 'false');
      var stored = searchReturnFocus;
      searchReturnFocus = null;
      var back = stored && stored.focus && stored !== doc.body && doc.contains(stored) ? stored : searchBtn;
      back.focus();
    }
    searchBtn.addEventListener('click', function () {
      if (searchPane.hasAttribute('hidden')) {
        searchReturnFocus = doc.activeElement;
        searchPane.removeAttribute('hidden');
        searchBtn.setAttribute('aria-expanded', 'true');
        var q = qs('#iw-q');
        if (q) { q.focus(); }
      } else {
        closeSearch();
      }
    });
    doc.addEventListener('keydown', function (ev) {
      if (ev.key === 'Escape' && !searchPane.hasAttribute('hidden')) { closeSearch(); return; }
      // Ctrl/Cmd+K anywhere, or "/" when not already typing, opens search.
      var typing = /^(INPUT|TEXTAREA|SELECT)$/.test((doc.activeElement || {}).tagName || '') ||
        (doc.activeElement && doc.activeElement.isContentEditable);
      var shortcut = ((ev.ctrlKey || ev.metaKey) && (ev.key || '').toLowerCase() === 'k') ||
        (ev.key === '/' && !typing && !ev.ctrlKey && !ev.metaKey && !ev.altKey);
      if (shortcut) {
        ev.preventDefault();
        if (searchPane.hasAttribute('hidden')) { searchBtn.click(); }
        else { var open = qs('#iw-q'); if (open) { open.focus(); } }
      }
    });
    // A click outside the open panel closes it, the way the menu does.
    doc.addEventListener('click', function (ev) {
      if (searchPane.hasAttribute('hidden')) { return; }
      if (searchPane.contains(ev.target) || searchBtn.contains(ev.target)) { return; }
      closeSearch();
    });
  }

  /* ---- Back to top ---------------------------------------------------- */
  var topBtn = qs('#iw-top');
  var progressBar = qs('#iw-progress-bar');
  var body = qs('#iw-postbody');

  function onScroll() {
    var y = window.scrollY || window.pageYOffset;
    if (topBtn) { topBtn.classList.toggle('is-on', y > 600); }
    if (progressBar && body) {
      var start = body.offsetTop;
      var span = body.offsetHeight - window.innerHeight + 220;
      var pct = span > 0 ? ((y - start) / span) * 100 : 0;
      progressBar.style.width = Math.max(0, Math.min(100, pct)) + '%';
    }
  }
  var ticking = false;
  window.addEventListener('scroll', function () {
    if (ticking) { return; }
    ticking = true;
    window.requestAnimationFrame(function () { onScroll(); ticking = false; });
  }, { passive: true });
  onScroll();

  if (topBtn) {
    topBtn.addEventListener('click', function () {
      window.scrollTo({ top: 0, behavior: reduceMotion ? 'auto' : 'smooth' });
    });
  }

  /* ---- Empty state for index views ------------------------------------ */
  var grid = qs('#iw-grid');
  var empty = qs('#iw-empty');
  var leadImage = grid ? qs('.iw-card:first-child .iw-card__media img', grid) : null;
  if (leadImage) {
    leadImage.loading = 'eager';
    leadImage.fetchPriority = 'high';
  }
  if (grid && empty && !grid.querySelector('.iw-card')) {
    grid.style.display = 'none';
    empty.removeAttribute('hidden');
  }
  var featuredFallback = qs('#FeaturedPost1');
  if (featuredFallback) {
    if (grid && grid.querySelector('.iw-card')) {
      featuredFallback.setAttribute('hidden', 'hidden');
    } else {
      var fallbackImage = qs('.item-thumbnail img', featuredFallback);
      if (fallbackImage) {
        fallbackImage.removeAttribute('srcset');
        fallbackImage.removeAttribute('sizes');
        fallbackImage.loading = 'eager';
        fallbackImage.fetchPriority = 'high';
      }
    }
  }

  /* ---- Card snippets -------------------------------------------------- *
     The server snippet arrives inside a template (see the iwCard comment), so
     a tag cut in half cannot leak. Only its plain text is shown. */
  qsa('template.iw-snippet-src').forEach(function (tpl) {
    var target = tpl.previousElementSibling;
    var text = (tpl.content ? tpl.content.textContent : tpl.textContent) || '';
    text = text.replace(/\s+/g, ' ').trim();
    if (target && target.classList.contains('iw-card__snippet')) {
      if (text) { target.textContent = text; } else { target.remove(); }
    }
    tpl.remove();
  });

  /* ---- Topic labels ---------------------------------------------------- *
     Posts carry many labels in alphabetical order, so a card used to show
     "Accessibility, Community feedback" for a dictionary release. Product
     areas come first, then the most specific remaining topic. */
  var AREAS = ['Mobile app', 'Android', 'Website', 'Public website', 'TribeStudio', 'Kasem Dictionary',
    'Dictionary', 'Kawuri', 'Contributors', 'Validators', 'Admin', 'Correspondence', 'Music', 'Learning', 'Kasem'];
  function rankLabels(links) {
    var seen = {};
    var unique = links.filter(function (a) {
      var name = (a.textContent || '').trim().toLowerCase();
      if (!name || seen[name]) { return false; }
      seen[name] = true;
      return true;
    });
    function area(a) {
      var name = (a.textContent || '').trim().toLowerCase();
      for (var i = 0; i < AREAS.length; i += 1) { if (AREAS[i].toLowerCase() === name) { return i; } }
      return AREAS.length;
    }
    return unique.map(function (a, i) { return { a: a, rank: area(a), i: i }; })
      .sort(function (x, y) { return x.rank - y.rank || x.i - y.i; })
      .map(function (x) { return x.a; });
  }
  qsa('.iw-card .iw-chips').forEach(function (wrap) {
    var ranked = rankLabels(qsa('a', wrap));
    ranked.forEach(function (a, i) {
      if (i < 2) { wrap.appendChild(a); } else { a.remove(); }
    });
  });
  var kicker = qs('.iw-kicker');
  if (kicker) {
    rankLabels(qsa('a', kicker)).forEach(function (a, i) {
      if (i < 3) { kicker.appendChild(a); } else { a.remove(); }
    });
  }

  // The sidebar keeps the twelve busiest topics in view, the rest behind a toggle.
  qsa('.iw-side .iw-labels').forEach(function (box) {
    var chips = qsa('.iw-chip', box);
    if (chips.length <= 14) { return; }
    var count = function (a) { var c = qs('.iw-labels__count', a); return c ? parseInt(c.textContent, 10) || 0 : 0; };
    chips.map(function (a, i) { return { a: a, n: count(a), i: i }; })
      .sort(function (x, y) { return y.n - x.n || x.i - y.i; })
      .forEach(function (x, rank) { if (rank >= 12) { x.a.classList.add('is-extra'); } });
    box.classList.add('is-trimmed');
    var more = doc.createElement('button');
    more.type = 'button';
    more.className = 'iw-labels__more';
    more.setAttribute('aria-expanded', 'false');
    more.textContent = 'Show all ' + chips.length + ' topics';
    more.addEventListener('click', function () {
      var open = box.classList.toggle('is-trimmed') === false;
      more.setAttribute('aria-expanded', open ? 'true' : 'false');
      more.textContent = open ? 'Show fewer topics' : 'Show all ' + chips.length + ' topics';
    });
    box.appendChild(more);
  });

  // Search results say how many updates matched on this page.
  var viewCount = qs('#iw-viewcount');
  if (viewCount && grid && !viewCount.textContent.trim() && /[?&]q=/.test(location.search)) {
    var found = qsa('.iw-card', grid).length;
    viewCount.textContent = found === 0 ? '' : found + (found === 1 ? ' update' : ' updates') +
      (qs('.iw-pager__link--next') ? ' on this page' : '') + ', newest first.';
  }

  /* ---- Sharper Popular Posts thumbnails -------------------------------- */
  qsa('.iw-pp__img').forEach(function (img) {
    var src = img.getAttribute('src') || '';
    img.setAttribute('src', src.replace(/\/s\d+(-c)?\//, '/s160-c/').replace(/=s\d+(-c)?$/, '=s160-c'));
  });

  /* ---- Article enhancements ------------------------------------------- */
  if (body) {
    // Estimated reading time
    var words = (body.textContent || '').trim().split(/\s+/).filter(Boolean).length;
    var mins = Math.max(1, Math.round(words / 200));
    var rt = qs('#iw-readtime');
    var rtDot = qs('#iw-rt-dot');
    if (rt) {
      rt.textContent = mins + ' min read';
      rt.removeAttribute('hidden');
      if (rtDot) { rtDot.removeAttribute('hidden'); }
    }

    /* ---- One cover, not two ------------------------------------------- *
       The theme renders the post's first image as the cover, and release
       posts open with that same image so Blogger uses it for the share card.
       Blogger rewrites the URL size segment (s1600, w1400-h787-...), so the
       comparison uses the stable image key and the file name. */
    var cover = qs('#iw-cover');
    var coverImg = cover ? qs('img', cover) : null;
    function imageKey(src) {
      // .../img/b/R29vZ2xl/<key>/s1600/name.png and .../img/a/<key>=s1600
      var m = (src || '').match(/\/img\/[a-z]\/(?:R29vZ2xl\/)?([^/=?]+)/i);
      if (m) { return m[1]; }
      // Anything else: the whole address without Blogger's size segments.
      return (src || '').split('?')[0]
        .replace(/\/(s\d+(-c)?|w\d+-h\d+[^/]*)\//, '/')
        .replace(/=(s|w)\d+[^/]*$/, '');
    }
    if (coverImg) {
      var coverKey = imageKey(coverImg.getAttribute('src'));
      // Blogger's featured image is the first image in the post, so only the
      // first body image can be the duplicate.
      var firstImgs = qsa('img', body).slice(0, 1);
      firstImgs.forEach(function (img) {
        if (!coverKey || imageKey(img.getAttribute('src')) !== coverKey) { return; }
        // Remove the smallest wrapper that holds nothing but this image, so
        // a paragraph that also carries text keeps its words.
        var box = img;
        while (box.parentNode && box.parentNode !== body && body.contains(box.parentNode) &&
               /^(A|P|DIV|FIGURE|ARTICLE)$/.test(box.parentNode.tagName)) {
          var parent = box.parentNode;
          var rest = Array.prototype.filter.call(parent.childNodes, function (n) {
            if (n === box) { return false; }
            if (n.nodeType === 3) { return n.textContent.trim() !== ''; }
            if (n.nodeType !== 1) { return false; }
            return n.tagName !== 'BR' && n.tagName !== 'FIGCAPTION';
          });
          if (rest.length || parent.tagName === 'ARTICLE') { break; }
          box = parent;
        }
        var caption = box.tagName === 'FIGURE' ? qs('figcaption', box) : null;
        if (caption && !qs('figcaption', cover)) { cover.appendChild(caption); }
        if (img.alt && img.alt.length > coverImg.alt.length) { coverImg.alt = img.alt; }
        box.remove();
      });
    }

    // Lazy-load and tidy images that came from the post editor
    qsa('img', body).forEach(function (img) {
      if (!img.getAttribute('loading')) { img.setAttribute('loading', 'lazy'); }
      if (!img.getAttribute('decoding')) { img.setAttribute('decoding', 'async'); }
    });

    // Give wide tables their own scroll container
    qsa('table', body).forEach(function (tbl) {
      if (tbl.parentNode && tbl.parentNode.classList.contains('iw-tablewrap')) { return; }
      var wrap = doc.createElement('div');
      wrap.className = 'iw-tablewrap';
      tbl.parentNode.insertBefore(wrap, tbl);
      wrap.appendChild(tbl);
    });

    // Outbound links open safely
    qsa('a[href]', body).forEach(function (a) {
      if (a.hostname && a.hostname !== location.hostname) {
        a.setAttribute('rel', 'noopener noreferrer');
      }
    });

    // Copy button on code blocks
    qsa('pre', body).forEach(function (pre) {
      var btn = doc.createElement('button');
      btn.type = 'button';
      btn.className = 'iw-copy';
      btn.textContent = 'Copy';
      btn.addEventListener('click', function () {
        var code = pre.querySelector('code');
        var text = code ? code.innerText : Array.prototype.map.call(pre.childNodes, function (node) {
          return node === btn ? '' : node.textContent;
        }).join('');
        var done = function () {
          btn.textContent = 'Copied';
          setTimeout(function () { btn.textContent = 'Copy'; }, 1600);
        };
        if (navigator.clipboard && navigator.clipboard.writeText) {
          navigator.clipboard.writeText(text).then(done, function () {});
        }
      });
      pre.appendChild(btn);
    });

    // Table of contents from the article's own headings
    var rail = qs('#iw-rail');
    var tocList = qs('#iw-toc-list');
    var heads = qsa('h2, h3', body).filter(function (h) { return (h.textContent || '').trim().length > 0; });
    if (rail && tocList && heads.length >= 3) {
      heads.forEach(function (h, i) {
        if (!h.id) {
          var slug = (h.textContent || '').toLowerCase().trim()
            .replace(/[^a-z0-9\s-]/g, '').replace(/\s+/g, '-').slice(0, 48);
          h.id = slug ? slug + '-' + i : 'section-' + i;
        }
        var a = doc.createElement('a');
        a.href = '#' + h.id;
        a.textContent = (h.textContent || '').trim();
        a.setAttribute('data-depth', h.tagName === 'H3' ? '3' : '2');
        tocList.appendChild(a);
      });
      rail.removeAttribute('hidden');
      var tocCount = qs('#iw-toc-count');
      var tocDetails = qs('#iw-toc-details');
      if (tocCount) { tocCount.textContent = '\u00b7 ' + heads.length + ' sections'; }

      // Keep the contents beside the article on desktop and before the prose
      // on smaller screens, with keyboard order matching the visual order.
      // Below the desktop breakpoint the list starts folded into one line.
      var articleLayout = rail.parentNode;
      var wideArticle = window.matchMedia('(min-width: 1180px)');
      function placeToc() {
        if (wideArticle.matches) { articleLayout.appendChild(rail); }
        else { body.parentNode.insertBefore(rail, body); }
        if (tocDetails) {
          tocDetails.open = wideArticle.matches;
          var sum = qs('summary', tocDetails);
          if (sum) { if (wideArticle.matches) { sum.setAttribute('tabindex', '-1'); } else { sum.removeAttribute('tabindex'); } }
        }
      }
      if (tocDetails) {
        tocDetails.addEventListener('toggle', function () {
          if (wideArticle.matches && !tocDetails.open) { tocDetails.open = true; }
        });
        // Choosing a section on a phone folds the list away again.
        tocList.addEventListener('click', function () {
          if (!wideArticle.matches) { tocDetails.open = false; }
        });
      }
      if (wideArticle.addEventListener) { wideArticle.addEventListener('change', placeToc); }
      placeToc();

      if ('IntersectionObserver' in window) {
        var links = qsa('a', tocList);
        var seen = {};
        var io = new IntersectionObserver(function (entries) {
          entries.forEach(function (en) { seen[en.target.id] = en.isIntersecting; });
          var active = null;
          heads.forEach(function (h) { if (seen[h.id] && !active) { active = h.id; } });
          links.forEach(function (l) {
            l.classList.toggle('is-active', active !== null && l.getAttribute('href') === '#' + active);
          });
        }, { rootMargin: '-90px 0px -70% 0px' });
        heads.forEach(function (h) { io.observe(h); });
      }
    }

    // Share row
    var shareBox = qs('#iw-share');
    if (shareBox) {
      var url = (doc.querySelector('link[rel="canonical"]') || {}).href || location.href;
      var titleNode = qs('.iw-article__title');
      var title = titleNode ? (titleNode.textContent || '').trim() : doc.title;
      var targets = [
        { name: 'X', href: 'https://twitter.com/intent/tweet?url=' + encodeURIComponent(url) + '&text=' + encodeURIComponent(title),
          path: 'M4 4l16 16M20 4L4 20' },
        { name: 'LinkedIn', href: 'https://www.linkedin.com/sharing/share-offsite/?url=' + encodeURIComponent(url),
          path: 'M6 9v10M6 5.5v.01M11 19v-6a3 3 0 016 0v6' },
        { name: 'WhatsApp', href: 'https://api.whatsapp.com/send?text=' + encodeURIComponent(title + ' ' + url),
          path: 'M21 12a9 9 0 01-13.4 7.8L3 21l1.3-4.4A9 9 0 1121 12z' },
        { name: 'Facebook', href: 'https://www.facebook.com/sharer/sharer.php?u=' + encodeURIComponent(url),
          path: 'M14 8h3V4h-3a4 4 0 00-4 4v3H7v4h3v6h4v-6h3l1-4h-4V8z' }
      ];
      targets.forEach(function (t) {
        var a = doc.createElement('a');
        a.href = t.href;
        a.target = '_blank';
        a.rel = 'noopener noreferrer';
        a.title = 'Share on ' + t.name;
        a.setAttribute('aria-label', 'Share on ' + t.name);
        a.innerHTML = '<svg aria-hidden="true" focusable="false" viewBox="0 0 24 24"><path d="' + t.path + '"/></svg>' +
          '<span>' + t.name + '</span>';
        shareBox.appendChild(a);
      });

      var copyBtn = doc.createElement('button');
      copyBtn.type = 'button';
      copyBtn.title = 'Copy link';
      copyBtn.innerHTML = '<svg aria-hidden="true" focusable="false" viewBox="0 0 24 24">' +
        '<path d="M10 13a4 4 0 006 .5l2-2a4 4 0 00-5.7-5.7l-1 1"/>' +
        '<path d="M14 11a4 4 0 00-6-.5l-2 2A4 4 0 009.7 18l1-1"/></svg>' +
        '<span aria-live="polite">Copy link</span>';
      var copyLabel = copyBtn.querySelector('span');
      function copied() {
        copyBtn.classList.add('is-copied');
        copyLabel.textContent = 'Copied';
        setTimeout(function () { copyBtn.classList.remove('is-copied'); copyLabel.textContent = 'Copy link'; }, 1800);
      }
      // Older in-app browsers (WhatsApp, Facebook) lack the async clipboard.
      function legacyCopy() {
        var field = doc.createElement('textarea');
        field.value = url;
        field.setAttribute('readonly', '');
        field.style.position = 'fixed';
        field.style.opacity = '0';
        doc.body.appendChild(field);
        field.select();
        var ok = false;
        try { ok = doc.execCommand('copy'); } catch (e) {}
        field.remove();
        if (ok) { copied(); } else { window.prompt('Copy this link', url); }
      }
      copyBtn.addEventListener('click', function () {
        if (navigator.clipboard && navigator.clipboard.writeText) {
          navigator.clipboard.writeText(url).then(copied, legacyCopy);
        } else {
          legacyCopy();
        }
      });
      shareBox.appendChild(copyBtn);

      if (navigator.share) {
        var nativeBtn = doc.createElement('button');
        nativeBtn.type = 'button';
        nativeBtn.title = 'Share';
        nativeBtn.innerHTML = '<svg aria-hidden="true" focusable="false" viewBox="0 0 24 24">' +
          '<circle cx="18" cy="5.5" r="2.5"/><circle cx="6" cy="12" r="2.5"/><circle cx="18" cy="18.5" r="2.5"/>' +
          '<path d="M8.2 10.8l7.6-4M8.2 13.2l7.6 4"/></svg><span>More</span>';
        nativeBtn.addEventListener('click', function () {
          navigator.share({ title: title, url: url }).catch(function () {});
        });
        shareBox.appendChild(nativeBtn);
      }

      // On wide screens sharing occupies the left rail, balancing the table
      // of contents on the right. It returns to the article footer elsewhere.
      var shareRail = qs('#iw-share-rail');
      var shareHome = shareBox.parentNode;
      var shareNext = shareBox.nextSibling;
      var wideShare = window.matchMedia('(min-width: 1180px)');
      function placeShare() {
        if (wideShare.matches && shareRail) {
          shareRail.appendChild(shareBox);
          shareRail.removeAttribute('hidden');
        } else if (shareHome) {
          shareHome.insertBefore(shareBox, shareNext);
          if (shareRail) { shareRail.setAttribute('hidden', 'hidden'); }
        }
      }
      if (wideShare.addEventListener) { wideShare.addEventListener('change', placeShare); }
      placeShare();
    }

    /* ---- Related posts, by the post's first label --------------------- */
    var relSection = qs('#iw-related');
    var relList = qs('#iw-related-list');
    var firstChip = qs('.iw-kicker a');
    if (relSection && relList && firstChip) {
      var label = (firstChip.textContent || '').trim();
      var relTopic = qs('#iw-related-topic');
      if (relTopic) { relTopic.textContent = label; }
      var feed = location.origin + '/feeds/posts/summary/-/' +
        encodeURIComponent(label) + '?alt=json&max-results=7';
      fetch(feed, { credentials: 'omit' })
        .then(function (r) { return r.ok ? r.json() : null; })
        .then(function (json) {
          if (!json || !json.feed || !json.feed.entry) { return; }
          var current = location.pathname;
          var made = 0;
          json.feed.entry.forEach(function (en) {
            if (made >= 3) { return; }
            var link = (en.link || []).filter(function (l) { return l.rel === 'alternate'; })[0];
            if (!link) { return; }
            var a = doc.createElement('a');
            a.href = link.href;
            if (a.pathname === current) { return; }
            a.className = 'iw-related__item';
            // Ask Blogger's image proxy for a cover-shaped crop.
            var thumb = en.media$thumbnail ? en.media$thumbnail.url
              .replace(/\/s\d+(-c)?\//, '/w480-h252-p-k-no-nu/')
              .replace(/=s\d+(-c)?$/, '=w480-h252-p-k-no-nu') : '';
            var when = en.published ? new Date(en.published.$t) : null;
            var whenText = when ? when.toLocaleDateString(undefined, { day: 'numeric', month: 'short', year: 'numeric' }) : '';
            // Posts with no image get the woven mark, so every row lines up.
            a.innerHTML =
              (thumb
                ? '<img class="iw-related__thumb" src="' + thumb + '" alt="" width="480" height="252" loading="lazy"/>'
                : '<span class="iw-related__motif">' +
                  '<svg aria-hidden="true" class="iw-mark" focusable="false" viewBox="0 0 64 64">' +
                  '<path class="iw-mark__frame" d="M15 47V23l17-9 17 9v24"/>' +
                  '<path class="iw-mark__line" d="M24 44V29m8 15V24m8 20V29"/>' +
                  '<circle class="iw-mark__sun" cx="32" cy="14" r="4"/></svg></span>') +
              '<span class="iw-related__text">' +
              '<span class="iw-related__t"></span><span class="iw-related__d"></span></span>';
            var t = a.querySelector('.iw-related__t');
            var d = a.querySelector('.iw-related__d');
            if (t) { t.textContent = en.title ? en.title.$t : link.href; }
            if (d) { d.textContent = whenText; }
            relList.appendChild(a);
            made += 1;
          });
          if (made > 0) { relSection.removeAttribute('hidden'); }
        })
        .catch(function () {});
    }

    /* ---- Comments, loaded on request ----------------------------------- *
       Scripts cloned out of a template are inert, so they are recreated in
       document order, each external one finishing before the next inline one
       runs; Blogger's iframe set-up otherwise runs before its library and
       leaves a comment box that cannot be typed in. */
    var gate = qs('#iw-comments-gate');
    var gateSrc = qs('#iw-comments-src');
    var gateMount = qs('#iw-comments-mount');
    if (gate && gateSrc && gateMount) {
      var loadComments = function () {
        if (!gate.open || gate.getAttribute('data-loaded')) { return; }
        gate.setAttribute('data-loaded', 'true');
        var fragment = gateSrc.content.cloneNode(true);
        qsa('iframe', fragment).forEach(function (frame) {
          if (!frame.getAttribute('title')) { frame.setAttribute('title', 'Comments'); }
        });
        var scripts = qsa('script', fragment).map(function (old) {
          var d = { attrs: [], text: old.textContent || '' };
          Array.prototype.forEach.call(old.attributes, function (a) { d.attrs.push([a.name, a.value]); });
          old.parentNode.removeChild(old);
          return d;
        });
        gateMount.appendChild(fragment);
        gateSrc.remove();
        (function run(i) {
          if (i >= scripts.length) { return; }
          var el = doc.createElement('script');
          scripts[i].attrs.forEach(function (a) { el.setAttribute(a[0], a[1]); });
          if (el.src) {
            el.onload = el.onerror = function () { run(i + 1); };
            gateMount.appendChild(el);
          } else {
            el.text = scripts[i].text;
            gateMount.appendChild(el);
            run(i + 1);
          }
        }(0));
      };
      gate.addEventListener('toggle', loadComments);
      // A link to a particular comment (#c123...) or to #comments opens it.
      if (/^#(c\d+|comments|iw-comments|comment-form)/.test(location.hash)) {
        gate.open = true;
        loadComments();
      }
    }

    /* ---- Structured data, built from the page's own meta tags ---------
       Built here rather than in the template so a title carrying a quote or a
       backslash is escaped by JSON.stringify instead of breaking the JSON. */
    try {
      var metaOf = function (attr, val) {
        var el = doc.querySelector('meta[' + attr + '="' + val + '"]');
        return el ? (el.getAttribute('content') || '').trim() : '';
      };
      var type = metaOf('property', 'og:type');
      if (type === 'article') {
        var timeEl = qs('.iw-meta time');
        var titleEl = qs('.iw-article__title');
        var canonEl = doc.querySelector('link[rel="canonical"]');
        var canonical = (canonEl && canonEl.href) || metaOf('property', 'og:url') || location.href;
        var heading = titleEl ? (titleEl.textContent || '').trim() : metaOf('property', 'og:title');
        var coverImg = qs('.iw-cover img');
        var image = (coverImg && coverImg.src) || metaOf('property', 'og:image');
        var published = timeEl ? timeEl.getAttribute('datetime') : '';

        var ld = {
          '@context': 'https://schema.org',
          '@type': 'BlogPosting',
          headline: heading,
          url: canonical,
          mainEntityOfPage: { '@type': 'WebPage', '@id': canonical },
          inLanguage: root.getAttribute('lang') || 'en',
          publisher: { '@id': 'https://indigenworld.com/#organization' },
          isPartOf: { '@id': 'https://updates.indigenworld.com/#website' }
        };
        var desc = metaOf('name', 'description') || metaOf('property', 'og:description');
        if (desc) { ld.description = desc; }
        if (image) { ld.image = image; }
        if (published) { ld.datePublished = published; ld.dateModified = published; }
        ld.author = { '@id': 'https://indigenworld.com/#organization' };

        var crumbs = [{
          '@type': 'ListItem', position: 1, name: 'Updates',
          item: location.origin + '/'
        }];
        var firstChipEl = qs('.iw-kicker a');
        if (firstChipEl) {
          crumbs.push({
            '@type': 'ListItem', position: 2,
            name: (firstChipEl.textContent || '').trim(), item: firstChipEl.href
          });
        }
        crumbs.push({ '@type': 'ListItem', position: crumbs.length + 1, name: heading, item: canonical });

        [ld, { '@context': 'https://schema.org', '@type': 'BreadcrumbList', itemListElement: crumbs }]
          .forEach(function (obj) {
            var s = doc.createElement('script');
            s.type = 'application/ld+json';
            s.textContent = JSON.stringify(obj);
            doc.head.appendChild(s);
          });
      }
    } catch (e) {}
  }
}());
//
